# ----------------------------
# ENUMERATIONS
# ----------------------------

class Team(Enum):
    RED = "Red"
    BLUE = "Blue"

class AgentRole(Enum):
    ATTACKER = "Attacker"
    DEFENDER = "Defender"
    SCOUT = "Scout"

class ObjectiveType(Enum):
    CAPTURE_FLAG = "Capture the Flag"
    DEFEND_BASE = "Defend the Base"
    ELIMINATE_ENEMIES = "Eliminate All Enemies"

class GameState(Enum):
    PREPARING = "Preparing"
    RUNNING = "Running"
    COMPLETED = "Completed"
    FAILED = "Failed"

class AbilityType(Enum):
    SPEED_BOOST = "Speed Boost"
    HEAL = "Heal"
    SHIELD = "Shield"
    STEALTH = "Stealth"

# ----------------------------
# DATA CLASSES
# ----------------------------

@dataclass
class Position:
    x: float
    y: float

    def distance_to(self, other: 'Position') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)

    def __hash__(self):
        return hash((self.x, self.y))

    def __eq__(self, other):
        return isinstance(other, Position) and self.x == other.x and self.y == other.y

@dataclass
class Agent:
    id: str
    team: Team
    role: AgentRole
    position: Position
    health: float = 100.0
    max_health: float = 100.0
    speed: float = 1.0
    abilities: Set[AbilityType] = field(default_factory=set)
    is_active: bool = True
    last_seen_enemy: Optional[Position] = None
    objective_progress: float = 0.0  # 0.0 to 1.0 for objectives
    communication_queue: queue.Queue = field(default_factory=lambda: queue.Queue())

    def receive_message(self, message: Dict[str, Any]):
        self.communication_queue.put(message)

    def read_messages(self) -> List[Dict[str, Any]]:
        messages = []
        while not self.communication_queue.empty():
            messages.append(self.communication_queue.get())
        return messages

    def use_ability(self, ability: AbilityType):
        if ability in self.abilities:
            if ability == AbilityType.SPEED_BOOST:
                self.speed *= 1.5
                logger.info(f"Agent {self.id} activated Speed Boost.")
            elif ability == AbilityType.HEAL:
                self.health = min(self.max_health, self.health + 30)
                logger.info(f"Agent {self.id} healed to {self.health}.")
            elif ability == AbilityType.SHIELD:
                logger.info(f"Agent {self.id} activated Shield.")
            elif ability == AbilityType.STEALTH:
                logger.info(f"Agent {self.id} activated Stealth.")

@dataclass
class Objective:
    type: ObjectiveType
    position: Position
    team: Team
    is_completed: bool = False
    required_agents: int = 1  # Number of agents needed to complete
    completed_by: Set[str] = field(default_factory=set)

    def add_completion(self, agent_id: str):
        self.completed_by.add(agent_id)
        self.is_completed = len(self.completed_by) >= self.required_agents

@dataclass
class MapTile:
    walkable: bool = True
    obstacle_type: Optional[str] = None

@dataclass
class GameMap:
    width: int
    height: int
    tiles: List[List[MapTile]] = field(default_factory=list)
    objectives: List[Objective] = field(default_factory=list)
    spawn_points: Dict[Team, List[Position]] = field(default_factory=dict)

    def __post_init__(self):
        self.tiles = [[MapTile() for _ in range(self.width)] for _ in range(self.height)]

    def is_valid_position(self, pos: Position) -> bool:
        if 0 <= pos.x < self.width and 0 <= pos.y < self.height:
            return self.tiles[int(pos.y)][int(pos.x)].walkable
        return False

    def add_objective(self, obj: Objective):
        self.objectives.append(obj)

    def add_spawn_point(self, team: Team, pos: Position):
        if team not in self.spawn_points:
            self.spawn_points[team] = []
        self.spawn_points[team].append(pos)

@dataclass
class GameStateManager:
    game_map: GameMap
    agents: List[Agent]
    team_scores: Dict[Team, int] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    current_state: GameState = GameState.PREPARING
    turn: int = 0
    max_turns: int = 300
    communication_channel: queue.Queue = field(default_factory=lambda: queue.Queue())

    def add_agent(self, agent: Agent):
        self.agents.append(agent)

    def broadcast_message(self, message: Dict[str, Any]):
        self.communication_channel.put(message)

    def distribute_messages(self):
        while not self.communication_channel.empty():
            message = self.communication_channel.get()
            for agent in self.agents:
                agent.receive_message(message)

    def update_objectives(self):
        for obj in self.game_map.objectives:
            if obj.type == ObjectiveType.CAPTURE_FLAG:
                # Check if agent is at flag position
                for agent in self.agents:
                    if agent.team == obj.team and agent.position.distance_to(obj.position) < 1.0:
                        obj.add_completion(agent.id)
                        if obj.is_completed:
                            self.team_scores[obj.team] += 10
                            logger.info(f"{obj.team.value} captured the flag!")
            elif obj.type == ObjectiveType.ELIMINATE_ENEMIES:
                # Count alive enemies
                alive_enemies = sum(1 for a in self.agents if a.team != obj.team and a.is_active)
                if alive_enemies == 0:
                    obj.is_completed = True
                    self.team_scores[obj.team] += 20
                    logger.info(f"{obj.team.value} eliminated all enemies!")
            elif obj.type == ObjectiveType.DEFEND_BASE:
                # Base is defended if no enemy is within 5 units of base for 10 turns
                base_pos = obj.position
                enemy_near_base = any(
                    a.team != obj.team and a.is_active and a.position.distance_to(base_pos) < 5.0
                    for a in self.agents
                )
                if not enemy_near_base:
                    obj.add_completion("defender")
                    if obj.is_completed:
                        self.team_scores[obj.team] += 15
                        logger.info(f"{obj.team.value} successfully defended the base!")

    def update_agents(self):
        for agent in self.agents:
            if not agent.is_active:
                continue
            # Read messages from communication channel
            messages = agent.read_messages()
            for msg in messages:
                if msg.get("type") == "enemy_spotted":
                    agent.last_seen_enemy = msg["position"]
                elif msg.get("type") == "objective_status":
                    agent.objective_progress = msg.get("progress", 0.0)

    def check_game_over(self) -> bool:
        if self.turn >= self.max_turns:
            self.current_state = GameState.FAILED
            logger.info("Game ended: Time limit reached.")
            return True

        completed_objectives = [obj for obj in self.game_map.objectives if obj.is_completed]
        if len(completed_objectives) >= len(self.game_map.objectives):
            self.current_state = GameState.COMPLETED
            logger.info("Game ended: All objectives completed.")
            return True

        # Check if one team has no active agents
        red_alive = sum(1 for a in self.agents if a.team == Team.RED and a.is_active)
        blue_alive = sum(1 for a in self.agents if a.team == Team.BLUE and a.is_active)
        if red_alive == 0 or blue_alive == 0:
            winner = Team.RED if blue_alive == 0 else Team.BLUE
            self.team_scores[winner] += 50  # Bonus for wiping out team
            self.current_state = GameState.COM

