import time
import math
import logging
from typing import List, Dict, Tuple, Optional, Set, Any
from enum import Enum
from dataclasses import dataclass, field
from collections import deque
import threading
import queue

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# ----------------------------
# ENUMERATIONS
# ----------------------------

class AgentRole(Enum):
    ATTACKER = "attacker"
    DEFENDER = "defender"
    SCOUT = "scout"
    HEALER = "healer"

class ObjectiveType(Enum):
    CAPTURE_FLAG = "capture_flag"
    DEFEND_BASE = "defend_base"
    ELIMINATE_ENEMIES = "eliminate_enemies"

class GameState(Enum):
    PREPARE = "prepare"
    ACTIVE = "active"
    COMPLETED = "completed"
    FAILED = "failed"

class AbilityType(Enum):
    SPEED_BOOST = "speed_boost"
    HEAL = "heal"
    SHIELD = "shield"
    SILENCE = "silence"
    TELEPORT = "teleport"

# ----------------------------
# DATA CLASSES
# ----------------------------

@dataclass
class Position:
    x: float
    y: float

    def distance_to(self, other: 'Position') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)

    def __hash__(self):
        return hash((self.x, self.y))

    def __eq__(self, other):
        return isinstance(other, Position) and self.x == other.x and self.y == other.y

@dataclass
class Agent:
    id: str
    role: AgentRole
    position: Position
    health: float = 100.0
    max_health: float = 100.0
    speed: float = 1.0
    abilities: List[AbilityType] = field(default_factory=list)
    team: str = "team_a"
    is_alive: bool = True
    cooldowns: Dict[AbilityType, float] = field(default_factory=dict)
    last_communication: float = 0.0
    target: Optional[Position] = None
    mission: Optional[ObjectiveType] = None

@dataclass
class Objective:
    type: ObjectiveType
    position: Position
    team_required: str
    captured: bool = False
    defenders: Set[str] = field(default_factory=set)
    flag_owner: Optional[str] = None  # For capture_flag
    enemy_count: int = 0  # For eliminate_enemies
    total_enemies: int = 0  # For eliminate_enemies

@dataclass
class Map:
    width: int
    height: int
    obstacles: Set[Position] = field(default_factory=set)
    spawn_points: Dict[str, List[Position]] = field(default_factory=dict)
    objectives: List[Objective] = field(default_factory=list)

@dataclass
class Message:
    sender_id: str
    content: str
    timestamp: float
    type: str = "info"  # "enemy_location", "objective_status", "strategy", "request_help"

@dataclass
class Team:
    name: str
    agents: List[Agent]
    score: int = 0
    base_position: Position

# ----------------------------
# COMMUNICATION SYSTEM
# ----------------------------

class CommunicationSystem:
    def __init__(self):
        self.message_queue: queue.Queue = queue.Queue()
        self.recent_messages: List[Message] = []
        self.max_messages = 50
        self.message_lock = threading.Lock()

    def broadcast(self, message: Message):
        with self.message_lock:
            self.message_queue.put(message)
            self.recent_messages.append(message)
            if len(self.recent_messages) > self.max_messages:
                self.recent_messages.pop(0)

    def get_recent_messages(self, agent_id: str, team: str) -> List[Message]:
        with self.message_lock:
            # Return messages relevant to agent's team or general info
            return [
                msg for msg in self.recent_messages
                if msg.sender_id != agent_id and (msg.type != "strategy" or team in msg.content)
            ]

    def get_messages_by_type(self, agent_id: str, message_type: str) -> List[Message]:
        with self.message_lock:
            return [
                msg for msg in self.recent_messages
                if msg.type == message_type and msg.sender_id != agent_id
            ]

# ----------------------------
# AI AGENT CONTROLLER
# ----------------------------

class AIController:
    def __init__(self, agent: Agent, team: Team, communication: CommunicationSystem, map_obj: Map):
        self.agent = agent
        self.team = team
        self.communication = communication
        self.map = map_obj
        self.current_mission = None
        self.pathfinding_cache = {}
        self.decision_cooldown = 0.5  # seconds between decisions
        self.last_decision_time = 0.0

    def update(self, current_time: float) -> Optional[str]:
        if not self.agent.is_alive:
            return "dead"

        if current_time - self.last_decision_time < self.decision_cooldown:
            return "waiting"

        self.last_decision_time = current_time
        self._update_cooldowns(current_time)
        self._receive_and_process_messages()
        self._assess_mission()
        self._execute_mission()

        return "active"

    def _update_cooldowns(self, current_time: float):
        for ability, cooldown_end in list(self.agent.cooldowns.items()):
            if current_time >= cooldown_end:
                del self.agent.cooldowns[ability]

    def _receive_and_process_messages(self):
        messages = self.communication.get_recent_messages(self.agent.id, self.team.name)
        for msg in messages:
            if msg.type == "enemy_location":
                try:
                    loc_str = msg.content.split(":")[1]
                    x, y = map(float, loc_str.split(","))
                    enemy_pos = Position(x, y)
                    self._set_target_if_closer(enemy_pos)
                except:
                    pass
            elif msg.type == "objective_status":
                try:
                    obj_type, status = msg.content.split(":")
                    if obj_type == self.agent.mission.value if self.agent.mission else "":
                        if status == "captured":
                            self.current_mission = None
                except:
                    pass
            elif msg.type == "strategy":
                if "capture_flag" in msg.content:
                    self.agent.mission = ObjectiveType.CAPTURE_FLAG
                elif "defend_base" in msg.content:
                    self.agent.mission = ObjectiveType.DEFEND_BASE

    def _assess_mission(self):
        # Default mission assignment based on role
        if not self.agent.mission:
            if self.agent.role == AgentRole.ATTACKER:
                for obj in self.map.objectives:
                    if obj.type == ObjectiveType.CAPTURE_FLAG and obj.team_required == self.team.name and not obj.captured:
                        self.agent.mission = ObjectiveType.CAPTURE_FLAG
                        break
            elif self.agent.role == AgentRole.DEFENDER:
                for obj in self.map.objectives:
                    if obj.type == ObjectiveType.DEFEND_BASE and obj.team_required == self.team.name:
                        self.agent.mission = ObjectiveType.DEFEND_BASE
                        break
            elif self.agent.role == AgentRole.SCOUT:
                self.agent.mission = ObjectiveType.ELIMINATE_ENEMIES  # Recon and eliminate
            elif self.agent.role == AgentRole.HEALER:
                self.agent.mission = None  # React to requests

        # If no mission, default to nearest objective
        if not self.agent.mission and self.map.objectives:
            closest_obj = min(self.map.objectives, key=lambda o: self.agent.position.distance_to(o.position))
            self.agent.mission = closest_obj.type

    def _execute_mission(self):
        if self.agent.mission == ObjectiveType.CAPTURE_FLAG:
            self._capture_flag()
        elif self.agent.mission == ObjectiveType.DEFEND_BASE:
            self._defend_base()
        elif self.agent.mission == ObjectiveType.ELIMINATE_ENEMIES:
            self._eliminate_enemies()
        else:
            self._patrol()

    def _capture_flag(self):
        flag_obj = None
        for obj in self.map.objectives:
            if obj.type == ObjectiveType.CAPTURE_FLAG and obj.team_required == self.team.name:
                flag_obj = obj
                break

