            self.memory.append({"event": world.last_event, "time": world.time})
            if len(self.memory) > 10:  # Limit memory size
                self.memory.pop(0)

        # AI Behavior Logic
        self._ai_behavior(dt, world)

    def _ai_behavior(self, dt: float, world: 'World'):
        if self.health <= 0:
            self.behavior_state = "DEAD"
            return

        # Find nearest enemy within vision range
        enemies = [r for r in world.robots if r.team != self.team and r.health > 0]
        nearest_enemy = None
        min_dist = float('inf')
