            if self.reload_timer <= 0 and self.ammo < self.weapon.magazine_size:
                self.ammo = self.weapon.magazine_size

        # Update power-up durations
        expired = []
        for power, duration in self.power_ups.items():
            self.power_ups[power] = duration - delta_time
            if self.power_ups[power] <= 0:
                expired.append(power)
        for exp in expired:
            del self.power_ups[exp]
            self.apply_power_up_effect(exp, remove=True)

        # Movement logic
        if self.target:
            direction = (self.target - self.position).normalize()
            self.velocity = direction * self.movement_speed
        else:
            self.velocity = Vector2(0, 0)

        self.position += self.velocity * delta_time

        # Clamp position within environment bounds
        self.position.x = max(0, min(self.position.x, environment.width))
        self.position.y = max(0, min(self.position.y, environment.height))

