        elif self.role == AIBehavior.DEFENSIVE:
            # Protect objective or base
            if self._has_protectable_objective(game_state):
                self.state = RobotState.DEFENDING
                return
            # Otherwise, stay near team
            team_positions = [r.position for r in game_state.robots if r.team == self.team and r.health > 0]
            if team_positions:
                center = self._calculate_center(team_positions)
                if self.position.distance_to(center) > 15:
                    self.state = RobotState.MOVING
                else:
                    self.state = RobotState.IDLE
                return

        elif self.role == AIBehavior.SUPPORT:
            # Heal or assist teammates
            teammates = [r for r in game_state.robots if r.team == self.team and r.health < r.max_health and r.health > 0]
            if teammates:
                weakest = min(teammates, key=lambda t: t.health)
                if self._can_heal(weakest) and self._in_range(weakest.position, 10):
                    self.state = RobotState.MOVING
                    return
            # Look for power-ups
            powerups = [p for p in game_state.power_ups.values() if p['active']]
            if powerups:
                closest_powerup = min(powerups, key=lambda p: self.position.distance_to(Position(p['x'], p['y'])))
                if self.position.distance_to(Position(closest_powerup['x'], closest_powerup['y'])) < 20:
                    self.state = RobotState.MOVING
                    return

        # Default: balanced behavior
        enemies = self._find_nearby_enemies(game_state)
        if enemies:
            nearest_enemy = min(enemies, key=lambda e: e['distance'])
            if nearest_enemy['distance'] < 15:
                if nearest_enemy['distance'] <= WEAPONS[self.weapon]['range']:
                    self.state = RobotState.ATTACKING
                else:
                    self.state = RobotState.MOVING
                return

        # Look for objectives
        objectives = game_state.objectives.values()
        if objectives:
            closest_obj = min(objectives, key=lambda obj: self.position.distance_to(obj.target_position))
            if self.position.distance_to(closest_obj.target_position) < 20:
                # If we can capture/defend/escort, do it
                self.objective = closest_obj.type
                if closest_obj.type == ObjectiveType.CAPTURE_FLAG:
                    self.state = RobotState.CAPTURING
                elif closest_obj.type == ObjectiveType.DEFEND_BASE:
                    self.state = RobotState.DEFENDING
                elif closest_obj.type == ObjectiveType.ESCORT_PAYLOAD:
                    self.state = RobotState.ESCORTING
                return

        # Idle or patrol if nothing urgent
        self.state = RobotState.IDLE if not enemies else RobotState.MOVING

    def _in_hazard(self, hazard: Dict, game_state: 'GameState') -> bool:
        """Check if robot is within a hazard area."""
        hazard_pos = Position(hazard['x'], hazard['y'])
        distance = self.position.distance_to(hazard_pos)
        return distance < hazard['radius']

    def _find_nearby_enemies(self, game_state: 'GameState') -> List[Dict]:
        """Find enemies within sensor range."""
        enemies = []
        for robot in game_state.robots:
            if robot.team != self.team and robot.health > 0:
                distance = self.position.distance_to(robot.position)
                if distance < 50:  # Sensor range
                    enemies.append({
                        'robot': robot,
                        'position': robot.position,
                        'distance': distance,
                        'health': robot.health,
                        'state': robot.state.value
                    })
        return enemies

    def _near_objective(self, target_pos: Position, threshold: float) -> bool:
        """Check if robot is near an objective."""
        return self.position.distance_to(target_pos) < threshold

    def _has_protectable_objective(self, game_state: 'GameState') -> bool:
        """Check if robot has a defendable objective."""
        for obj in game_state.objectives.values():
            if obj.type == ObjectiveType.DEFEND_BASE:
                if self._near_objective(obj.target_position, 15):
                    return True
        return False

    def _calculate_center(self, positions: List[Position]) -> Position:
        """Calculate center of a group of positions."""
        if not positions:
            return Position(0, 0)
        sum_x = sum(p.x for p in positions)
        sum_y = sum(p.y for p in positions)
        count = len(positions)
        return Position(sum_x / count, sum_y / count)

    def _can_heal(self, teammate: 'Robot') -> bool:
        """Check if this robot can heal a teammate."""
        return 'health_pack' in self.inventory and self.health > 20

    def _in_range(self, target_pos: Position, range_: float) -> bool:
        """Check if target is in range."""
        return self.position.distance_to(target_pos) <= range_

    def attack(self, target: 'Robot', game_state: 'GameState') -> bool:
        """Attempt to attack a target with current weapon."""
        weapon = WEAPONS[self.weapon]
        distance = self.position.distance_to(target.position)

        # Range check
        if distance > weapon['range']:
            return False

        # Cooldown check
        if self.cooldown > 0:
            return False

        # Apply damage
        damage = weapon['damage'] * self.damage_boost
        if target.shield > 0:
            damage_taken = min(damage, target.shield)
            target.shield -= damage_taken
            damage = damage - damage_taken

        target.health -= damage
        target.health = max(0, target.health)

        # Create damage effect
        if damage > 0:
            game_state.effects.append({
                'type': 'damage',
                'position': target.position,
                'color': 'red',
                'duration': 0.5
            })

        # Update cooldown
        self.cooldown = weapon['cooldown']

        # Record in knowledge base
        self.knowledge_base['battle_history'].append({
            'action': 'attack',
            'target': target.id,
            'damage': damage,
            'timestamp': time.time()
        })

        # Add to communication
        self.team_coordination['communication'].append({
            'action': 'attacked',
            'target': target.id,
            'damage': damage,
            'timestamp': time.time()
        })

        return True

    def use_power_up(self, power_up_name: str, game_state: 'GameState'):
        """Use a power-up from inventory."""
        if power_up_name not in self.inventory:
            return

        power_up = POWER_UPS[power_up_name]
        self.inventory.remove(power_up_name)

        if power_up['effect'] == 'heal':
            self.health = min(self.max_health, self.health + power_up['heal_amount'])
            game_state.effects.append({
                'type': 'heal',
                'position': self.position,
                'color': 'green',
                'duration': 1.0
            })

        elif power_up['effect'] == 'speed':
            self.speed_boost = power_up['bonus_speed']
            game_state.effects.append({
                'type': 'speed',
                'position': self.position,
                'color': 'blue',
                'duration': 0.5
            })

        elif power_up['effect'] == 'damage':
            self.damage_boost = power_up['bonus_damage']
            game_state.effects.append({
                'type': 'damage',
                'position': self.position,
                'color': 'orange',
                'duration': 0.5
            })

        elif power_up['effect'] == 'shield':
            self.shield = power_up['absorption']
            game_state.effects.append({
                'type': 'shield',
                'position': self.position,
                'color': 'cyan',
                'duration': 0.5
            })

        elif power_up['effect'] == 'radar':
            self.radar_active = True
            self.radar_range = power_up['duration']
            game_state.effects.append({
                'type': 'radar',
                'position': self.position,
                'color': 'purple',
                'duration': 0.5
            })

        elif power_up['effect'] == 'teleport':
            # Teleport to random location within map
            self.position = Position(
                random.uniform(0, MAP_SIZE[0]),
                random.uniform(0, MAP_SIZE[1])
            )
            game_state.effects.append({
                'type': 'teleport',
                'position': self.position,
                'color': 'yellow',
                'duration': 0.8
            })

    def move_towards(self, target_pos: Position, game_state: 'GameState'):
        """Move robot towards a target position."""
        if self.state == RobotState.DEAD:
            return

        direction = (target_pos - self.position).normalize()
        move_distance = self.speed * self.speed_boost * UPDATE_INTERVAL

        new_x = self.position.x + direction.x * move_distance
        new_y = self.position.y + direction.y * move_distance

        # Boundary check
        new_x = max(0, min(MAP_SIZE[0], new_x))
        new_y = max(0, min(MAP_SIZE[1], new_y))

        self.position = Position(new_x, new_y)
        self.state = RobotState.MOVING

        # Check for power-up pickup
        for power_up_id, power_up in game_state.power_ups.items():
            if power_up['active']:
                power_pos = Position(power_up['x'], power_up['y'])
                if self.position.distance_to(power_pos) < 3:
                    self.inventory.append(power_up['type'])
                    power_up['active'] = False
                    game_state.effects.append({
                        'type': 'pickup',
                        'position': self.position,
                        'color': 'gold',
                        'duration': 0.5
                    })

    def take_damage(self, amount: float):
        """Take damage, accounting for shield."""
        if self.shield > 0:
            shield_absorption = min(self.shield, amount)
            self.shield -= shield_absorption
            amount -= shield_absorption

        self.health -= amount
        self.health = max(0, self.health)

        if self.health <= 0:
            self.state = RobotState.DEAD
            self.health = 0

@dataclass
class Objective:
    type: ObjectiveType
    target_position: Position
    team: TeamColor
    completed: bool = False
    progress: float = 0.0
    duration: float = 0.0
    capture_threshold: float = 0.7  # 70% of robots must be near to capture flag

@dataclass
class GameStats:
    team_scores: Dict[TeamColor, int] = field(default_factory=lambda: {team: 0 for team in TeamColor})
    total_battles: int = 0
    average_game_duration: float = 0.0
    team_performance: Dict[TeamColor, Dict] = field(default_factory=dict)

    def __post_init__(self):
        for team in TeamColor:
            self.team_performance[team] = {
                'wins': 0,
                'kills': 0,
                'deaths': 0,
                'objectives_completed': 0,
                'teamwork_score': 0.0
            }

@dataclass
class GameState:
    robots: List[Robot] = field(default_factory=list)
    objectives: Dict[ObjectiveType, Objective] = field(default_factory=dict)
    power_ups: Dict[str, Dict] = field(default_factory=dict)
    hazards: Dict[str, Dict] = field(default_factory=dict)
    effects: List[Dict] = field(default_factory=list)
    game_time: float = 0.0
    is_running: bool = False
    winner: Optional[TeamColor] = None
    stats: GameStats = field(default_factory=GameStats)

    def __post_init__(self):
        # Initialize hazards
        self._generate_hazards()

        # Initialize power-ups
        self._generate_power_ups()

        # Initialize objectives
        self._generate_objectives()

    def _generate_hazards(self):
        """Generate random environmental hazards."""
        hazard_types = list(HAZARDS.keys())
        num_hazards = random.randint(3, 6)

        for i in range(num_hazards):
            hazard_type = random.choice(hazard_types)
            hazard = HAZARDS[hazard_type].copy()
            hazard['x'] = random.uniform(10, MAP_SIZE[0] - 10)
            hazard['y'] = random.uniform(10, MAP_SIZE[1] - 10)
            hazard['active'] = True
            self.hazards[f'hazard_{i}'] = hazard

    def _generate_power_ups(self):
        """Generate random power-ups."""
        power_up_types = list(POWER_UPS.keys())
        num_power_ups = random.randint(8, 12)

        for i in range(num_power_ups):
            power_up_type = random.choice(power_up_types)
            power_up = POWER_UPS[power_up_type].copy()
            power_up['x'] = random.uniform(5, MAP_SIZE[0] - 5)
            power_up['y'] = random.uniform(5, MAP_SIZE[1] - 5)
            power_up['active'] = True
            power_up['spawn_time'] = time.time()
            self.power_ups[f'powerup_{i}'] = power_up

    def _generate_objectives(self):
        """Generate objectives for the current game."""
        objective_types = list(ObjectiveType)
        num_objectives = random.randint(1, 2)

        # Create at least one objective
        for i in range(num_objectives):
            obj_type = random.choice(objective_types)
            team = random.choice(list(TeamColor))

            # Position based on objective type
            if obj_type == ObjectiveType.CAPTURE_FLAG:
                # Place flag in neutral territory
                x = random.uniform(MAP_SIZE[0]/3, MAP_SIZE[0]*2/3)
                y = random.uniform(MAP_SIZE[1]/3, MAP_SIZE[1]*2/3)
            elif obj_type == ObjectiveType.DEFEND_BASE:
                # Place base near team spawn
                x = random.uniform(10, 20) if team == TeamColor.RED else random.uniform(MAP_SIZE[0]-20, MAP_SIZE[0]-10)
                y = random.uniform(10, MAP_SIZE[1]-10)
            elif obj_type == ObjectiveType.ESCORT_PAYLOAD:
                # Spawn payload near one team
                x = random.uniform(10, 20) if team == TeamColor.RED else random.uniform(MAP_SIZE[0]-20, MAP_SIZE[0]-10)
                y = random.uniform(10, MAP_SIZE[1]-10)
            else:  # TERRITORY_CONTROL
                x = random.uniform(MAP_SIZE[0]/4, MAP_SIZE[0]*3/4)
                y = random.uniform(MAP_SIZE[1]/4, MAP_SIZE[1]*3/4)

            objective = Objective(
                type=obj_type,
                target_position=Position(x, y),
                team=team
            )
            self.objectives[obj_type] = objective

# ----------------------------
# ADAPTIVE DIFFICULTY SYSTEM
# ----------------------------

class AdaptiveDifficulty:
    def __init__(self, game_state: GameState):
        self.game_state = game_state
        self.difficulty_level = 1.0  # 1.0 = normal, >1.0 = harder, <1.0 = easier
        self.performance_history = deque(maxlen=20)
        self.last_adjustment_time = time.time()
        self.adjustment_cooldown = 15  # Seconds between adjustments

    def update(self):
        """Update difficulty based on team performance."""
        if time.time() - self.last_adjustment_time < self.adjustment_cooldown:
            return

        # Calculate team performance metrics
        team_performance = {}
        for team in TeamColor:
            stats = self.game_state.stats.team_performance[team]
            if stats['deaths'] == 0:
                kd_ratio = stats['kills']
            else:
                kd_ratio = stats['kills'] / stats['deaths']

            teamwork_score = stats['teamwork_score']
            objectives_completed = stats['objectives_completed']

            # Combined performance score
            performance = (kd_ratio * 0.4 + teamwork_score * 0.3 + objectives_completed * 0.3)
            team_performance[team] = performance

        # Calculate average performance
        avg_performance = sum(team_performance.values()) / len(team_performance)

        # Add to history
        self.performance_history.append(avg_performance)

        # Adjust difficulty based on performance trend
        if len(self.performance_history) >= 5:
            recent_avg = sum(list(self.performance_history)[-5:]) / 5
            prev_avg = sum(list(self.performance_history)[:5]) / 5 if len(self.performance_history) > 5 else recent_avg

            if recent_avg > prev_avg * 1.2:  # Too easy
                self.difficulty_level = min(2.0, self.difficulty_level * 1.1)
            elif recent_avg < prev_avg * 0.8:  # Too hard
                self.difficulty_level = max(0.5, self.difficulty_level * 0.9)

        # Apply difficulty adjustments to AI behavior
        self._apply_difficulty_adjustments()

        self.last_adjustment_time = time.time()

    def _apply_difficulty_adjustments(self):
        """Apply difficulty adjustments to AI behavior."""
        difficulty = self.difficulty_level

        for robot in self.game_state.robots:
            if robot.team != TeamColor.RED:  # Assume RED is player team, others are AI
                # Adjust AI aggression based on difficulty
                if difficulty > 1.2:
                    if robot.role == AIBehavior.BALANCED:
                        robot.role = AIBehavior.AGGRESSIVE
                    elif robot.role == AIBehavior.DEFENSIVE:
                        robot.role = AIBehavior.BALANCED
                    elif robot.role == AIBehavior.SUPPORT:
                        robot.role = AIBehavior.DEFENSIVE

                elif difficulty < 0.8:
                    if robot.role == AIBehavior.AGGRESSIVE:
                        robot.role = AIBehavior.BALANCED
                    elif robot.role == AIBehavior.BALANCED:
                        robot.role = AIBehavior.DEFENSIVE
                    elif robot.role == AIBehavior.DEFENSIVE:
                        robot.role = AIBehavior.SUPPORT

                # Adjust AI reaction speed (faster decision making)
                robot.speed *= (1 + (difficulty - 1.0) * 0.2)
                robot.speed = max(1.0, min(4.0, robot.speed))

                # Adjust weapon selection (better weapons more often)
                if random.random() < (difficulty - 0.5) * 0.2:
                    # Upgrade weapon if possible
                    weapons = ['laser_rifle', 'plasma_cannon', 'railgun']
                    current_index = weapons.index(robot.weapon) if robot.weapon in weapons else 0
                    new_index = min(len(weapons) - 1, current_index + int((difficulty - 1.0) * 2))
                    robot.weapon = weapons[new_index]

# ----------------------------
# LEARNING AND ADAPTATION SYSTEM
# ----------------------------

class LearningSystem:
    def __init__(self, game_state: GameState):
        self.game_state = game_state
        self.learning_rate = 0.1
        self.memory_size = 100
        self.strategy_memory = deque(maxlen=self.memory_size)
        self.team_strategy_history = defaultdict(lambda: deque(maxlen=20))

    def learn_from_battle(self):
        """Learn from the most recent battle and update strategies."""
        if not self.game_state.is_running:
            # Extract data from completed battle
            battle_data = self._extract_battle_data()
            if battle_data:
                self.strategy_memory.append(battle_data)
                self._update_team_strategies(battle_data)
                self._adjust_robot_strategies()

    def _extract_battle_data(self) -> Optional[Dict]:
        """Extract performance data from the completed battle."""
        if self.game_state.winner is None:
            return None

        # Create detailed battle data
        battle_data = {
            'winner': self.game_state.winner,
            'game_time': self.game_state.game_time,
            'team_scores': {team: self.game_state.stats.team_performance[team].copy() for team in TeamColor},
            'robot_performance': {},
            'objectives': []
        }

        # Robot performance
        for robot in self.game_state.robots:
            battle_data['robot_performance'][robot.id] = {
                'team': robot.team,
                'kills': len([x for x in robot.knowledge_base['battle_history'] if x['action'] == 'attack']),
                'deaths': 1 if robot.health <= 0 else 0,
                'teamwork': len(robot.team_coordination['communication']),
                'objectives_completed': len([o for o in robot.knowledge_base['battle_history'] if o['action'] == 'objective_completed']),
                'power_ups_used': len([p for p in robot.inventory if p in POWER_UPS]),
                'time_alive': robot.knowledge_base.get('time_alive', self.game_state.game_time)
            }

        # Objectives data
        for obj_type, obj in self.game_state.objectives.items():
            battle_data['objectives'].append({
                'type': obj_type.value,
                'team': obj.team.value,
                'completed': obj.completed,
                'progress': obj.progress
            })

        return battle_data

    def _update_team_strategies(self, battle_data: Dict):
        """Update team-specific strategies based on battle performance."""
        for team in TeamColor:
            team_data = battle_data['team_scores'][team]
            # Update team strategy based on wins, kills, teamwork
            if team_data['wins'] > 0:
                self.team_strategy_history[team].append({
                    'strategy': 'aggressive' if team_data['kills'] > team_data['deaths'] * 1.5 else 'balanced',
                    'wins': team_data['wins'],
                    'teamwork_score': team_data['teamwork_score']
                })

    def _adjust_robot_strategies(self):
        """Adjust robot strategies based on historical learning."""
        # For each robot, analyze their past performance and adjust
        for robot in self.game_state.robots:
            # Get robot's own history
            history = robot.knowledge_base['battle_history']
            if len(history) < 5:
                continue

            # Calculate success rate
            successful_attacks = len([x for x in history if x['action'] == 'attack' and x['damage'] > 10])
            total_attacks = len([x for x in history if x['action'] == 'attack'])

            if total_attacks > 0:
                success_rate = successful_attacks / total_attacks
            else:
                success_rate = 0.5

            # Adjust role based on success rate and team needs
            if success_rate > 0.7 and robot.health_rate > 0.8:  # High success, high survival
                robot.role = AIBehavior.AGGRESSIVE
            elif success_rate < 0.3 and robot.health_rate < 0.5:  # Low success, low survival
                robot.role = AIBehavior.SUPPORT
            else:
                robot.role = AIBehavior.BALANCED

            # Update weapon preference based on effectiveness
            weapon_performance = {}
            for weapon in WEAPONS.keys():
                hits = len([x for x in history if x['action'] == 'attack' and x['weapon'] == weapon])
                damage = sum([x['damage'] for x in history if x['action'] == 'attack' and x['weapon'] == weapon])
                weapon_performance[weapon] = (hits, damage)

            # Find best performing weapon
            best_weapon = max(weapon_performance.keys(), key=lambda w: weapon_performance[w][1])
            robot.weapon = best_weapon

# ----------------------------
# MAIN GAME SYSTEM
# ----------------------------

class CyberArena:
    def __init__(self):
        self.game_state = GameState()
        self.adaptive_difficulty = AdaptiveDifficulty(self.game_state)
        self.learning_system = LearningSystem(self.game_state)
        self.is_running = False
        self.last_update = time.time()
        self.update_thread = None

        # Initialize game
        self._initialize_game()

    def _initialize_game(self):
        """Initialize the game environment with robots and game state."""
        # Create teams
        team_colors = list(TeamColor)
        num_teams = min(random.randint(2, 4), len(team_colors))

        # Create robots
        robots = []
        robot_id = 0

        for team_index in range(num_teams):
            team = team_colors[team_index]
            num_robots = random.randint(1, MAX_ROBOTS_PER_TEAM)

            for _ in range(num_robots):
                # Define spawn zone per team
                if team == TeamColor.RED:
                    spawn_x = random.uniform(5, 15)
                    spawn_y = random.uniform(5, MAP_SIZE[1] - 5)
                elif team == TeamColor.BLUE:
                    spawn_x = random.uniform(MAP_SIZE[0] - 15, MAP_SIZE[0] - 5)
                    spawn_y = random.uniform(5, MAP_SIZE[1] - 5)
                elif team == TeamColor.GREEN:
                    spawn_x = random.uniform(MAP_SIZE[0]/3, MAP_SIZE[0]/3 + 10)
                    spawn_y = random.uniform(MAP_SIZE[1]/3, MAP_SIZE[1]/3 + 10)
                else:  # YELLOW
                    spawn_x = random.uniform(MAP_SIZE[0]*2/3 - 10, MAP_SIZE[0]*2/3)
                    spawn_y = random.uniform(MAP_SIZE[1]*2/3 - 10, MAP_SIZE[1]*2/3)

                # Random weapon selection
                weapon = random.choice(list(WEAPONS.keys()))

                # Random role selection
                role = random.choice(list(AIBehavior))

                robot = Robot(
                    id=f"robot_{robot_id}",
                    team=team,
                    position=Position(spawn_x, spawn_y),
                    weapon=weapon,
                    role=role
                )
                robots.append(robot)
                robot_id += 1

        self.game_state.robots = robots
        self.game_state.is_running = False

    def start_game(self):
        """Start the game loop."""
        if self.is_running:
            return

        self.is_running = True
        self.game_state.is_running = True
        self.game_state.winner = None
        self.game_state.game_time = 0.0
        self.last_update = time.time()

        # Start game loop in separate thread
        self.update_thread = threading.Thread(target=self._game_loop)
        self.update_thread.daemon = True
        self.update_thread.start()

    def stop_game(self):
        """Stop the game loop."""
        self.is_running = False
        self.game_state.is_running = False
        if self.update_thread:
            self.update_thread.join(timeout=1.0)

    def _game_loop(self):
        """Main game loop running in background thread."""
        while self.is_running:
            current_time = time.time()
            delta_time = current_time - self.last_update
            self.last_update = current_time

            # Update game time
            self.game_state.game_time += delta_time

            # Update robots
            for robot in self.game_state.robots:
                if robot.health > 0:
                    robot.update(delta_time, self.game_state)
                    self._update_robot_behavior(robot, delta_time)

            # Update objectives
            self._update_objectives()

            # Update hazards
            self._update_hazards()

            # Update power-ups
            self._update_power_ups()

            # Update effects
            self._update_effects(delta_time)

            # Check game end conditions
