            self.flag_position = Vector2D(SCREEN_WIDTH/2, SCREEN_HEIGHT/2)

    def get_allies(self, team_id: int) -> List[Robot]:
        return [robot for robot in self.robots if robot.team == team_id and robot.is_alive]

    def get_enemies(self, team_id: int) -> List[Robot]:
        return [robot for robot in self.robots if robot.team != team_id and robot.is_alive]

    def get_team_score(self, team_id: int) -> int:
        for team in self.teams:
            if team['id'] == team_id:
                return team['score']
        return 0

    def update(self, dt):
