        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        return Vector2D(self.x / scalar, self.y / scalar)

    def length(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        length = self.length()
        if length == 0:
            return Vector2D(0, 0)
        return self / length

    def distance_to(self, other):
        return (self - other).length()

    def rotate(self, angle_degrees):
        radians = math.radians(angle_degrees)
        cos_a = math.cos(radians)
        sin_a = math.sin(radians)
        return Vector2D(
            self.x * cos_a - self.y * sin_a,
            self.x * sin_a + self.y * cos_a
        )

@dataclass
class Weapon:
    type: WeaponType
    damage: float
    range: float
    fire_rate: float  # seconds between shots
    ammo: int
    max_ammo: int
    projectile_speed: float = 10.0
    splash_radius: float = 0.0
    cooldown: float = 0.0

    def can_fire(self):
        return self.cooldown <= 0 and self.ammo > 0

    def fire(self):
        if self.can_fire():
            self.ammo -= 1
            self.cooldown = self.fire_rate
            return True
        return False

    def update(self, dt):
        if self.cooldown > 0:
            self.cooldown -= dt

@dataclass
class Robot:
    id: int
    team: int
    role: RobotRole
    position: Vector2D
    velocity: Vector2D
    health: float
    max_health: float
    armor: float
    speed: float
    rotation: float  # in degrees
    weapon: Weapon
    abilities: Dict[str, float]  # ability_name -> cooldown_remaining
    vision_range: float = 150.0
    is_alive: bool = True
    last_seen_enemy: Optional[Vector2D] = None
    objectives: List[str] = None  # List of current objectives
    strategy_memory: List[Dict] = None  # Historical strategy data

    def __post_init__(self):
        if self.objectives is None:
            self.objectives = []
        if self.abilities is None:
            self.abilities = {}
        if self.strategy_memory is None:
            self.strategy_memory = []

    def update(self, dt):
        # Update weapon cooldown
        self.weapon.update(dt)

        # Update ability cooldowns
        for ability, cooldown in list(self.abilities.items()):
            if cooldown > 0:
                self.abilities[ability] = max(0, cooldown - dt)

        # Update position based on velocity
        self.position += self.velocity * dt

        # Apply friction
        self.velocity *= 0.95

        # Keep robot within bounds
        self.position.x = max(10, min(SCREEN_WIDTH - 10, self.position.x))
        self.position.y = max(10, min(SCREEN_HEIGHT - 10, self.position.y))

        # Check if robot is dead
        if self.health <= 0:
            self.is_alive = False

    def apply_force(self, force: Vector2D):
        # Apply force to velocity with mass (robots have mass based on armor)
        mass = 1 + (self.armor / 10)
        self.velocity += force / mass

    def find_nearest_target(self, enemies: List['Robot']) -> Optional['Robot']:
        """Find the nearest enemy within vision range"""
        nearest = None
        min_dist = float('inf')

        for enemy in enemies:
            if not enemy.is_alive:
                continue
            dist = self.position.distance_to(enemy.position)
            if dist < self.vision_range and dist < min_dist:
                min_dist = dist
                nearest = enemy

        return nearest

    def can_see_target(self, target: 'Robot') -> bool:
        """Check if this robot can see the target (line of sight)"""
        if self.position.distance_to(target.position) > self.vision_range:
            return False

        # Simple line of sight check - no obstacles in this basic version
        return True

    def get_action_priority(self, game_state: 'GameState') -> str:
        """Determine the highest priority action based on role and situation"""
        # Get nearest enemy
        nearest_enemy = self.find_nearest_target(game_state.get_enemies(self.team))

        if not self.is_alive:
            return "dead"

        # Check for critical health
        if self.health < self.max_health * 0.2:
            return "retreat" if self.role != RobotRole.SUPPORT else "heal"

        # Check for objectives
        if self.objectives:
            # If we have an objective, prioritize it
            for obj in self.objectives:
                if obj == "capture_flag" and game_state.flag_carrier_id != self.id:
                    return "capture_flag"
                elif obj == "defend_base":
                    return "defend_base"
                elif obj == "escort_payload":
                    return "escort_payload"

        # Role-based decision making
        if self.role == RobotRole.ATTACKER:
            if nearest_enemy and self.weapon.can_fire():
                return "attack"
            elif nearest_enemy:
                return "move_to_enemy"
            else:
                return "explore"

        elif self.role == RobotRole.DEFENDER:
            if nearest_enemy and nearest_enemy.position.distance_to(game_state.bases[self.team]) < 200:
                return "defend_base"
            elif nearest_enemy:
                return "engage"
            else:
                return "patrol_base"

        elif self.role == RobotRole.SUPPORT:
            if self.health < self.max_health * 0.7:
                return "heal"
            else:
                # Support nearby allies
                allies = game_state.get_allies(self.team)
                nearest_allied_low_health = None
                min_health = float('inf')

                for ally in allies:
                    if ally.is_alive and ally.health < ally.max_health * 0.5 and ally.position.distance_to(self.position) < 100:
                        if ally.health < min_health:
                            min_health = ally.health
                            nearest_allied_low_health = ally

                if nearest_allied_low_health:
                    return "heal_allied"
                else:
                    return "support_attack"

        elif self.role == RobotRole.SCOUT:
            if nearest_enemy:
                return "report_enemy"
            else:
                return "explore"

        return "idle"

@dataclass
class Objective:
    type: str  # 'flag', 'payload', 'base'
    position: Vector2D
    team: int  # which team owns or is defending this
    captured: bool = False
    progress: float = 0.0  # 0.0 to 1.0 for capture/escort progress
    owner_team: Optional[int] = None  # Which team currently owns it
    capture_radius: float = 50.0
    health: float = 100.0

    def update(self, dt, game_state: 'GameState'):
        # Update capture progress if robots are nearby
        if self.type == 'flag' and not self.captured:
            allies = game_state.get_allies(self.team)
            enemies = game_state.get_enemies(self.team)

            # Count nearby allies and enemies
            nearby_allies = sum(1 for ally in allies 
                               if ally.is_alive and ally.position.distance_to(self.position) < self.capture_radius)
            nearby_enemies = sum(1 for enemy in enemies 
                                if enemy.is_alive and enemy.position.distance_to(self.position) < self.capture_radius)

            # Capture logic
            if nearby_allies > 0 and nearby_enemies == 0:
                self.progress += dt * 0.3  # Capture rate
                if self.progress >= 1.0:
                    self.captured = True
                    self.owner_team = self.team
                    self.progress = 1.0
            elif nearby_enemies > 0 and nearby_allies == 0:
                self.progress -= dt * 0.2  # Reverse capture rate
                if self.progress <= 0.0:
                    self.captured = False
                    self.owner_team = None
                    self.progress = 0.0
            elif nearby_allies > 0 and nearby_enemies > 0:
                # Balanced conflict - capture progress slows
                if self.progress > 0.5:
                    self.progress -= dt * 0.05
                else:
                    self.progress += dt * 0.05

@dataclass
class PowerUp:
    type: PowerUpType
    position: Vector2D
    active: bool = True
    duration: float = 10.0  # seconds
    time_left: float = 10.0

    def update(self, dt):
        if self.active:
            self.time_left -= dt
            if self.time_left <= 0:
                self.active = False

@dataclass
class Hazard:
    type: HazardType
    position: Vector2D
    radius: float
    damage_per_second: float
    active: bool = True
    flicker_timer: float = 0.0

    def update(self, dt):
        self.flicker_timer += dt

    def affect_robot(self, robot: Robot) -> float:
        """Apply damage to robot and return damage amount"""
        if not self.active:
            return 0.0
        distance = robot.position.distance_to(self.position)
        if distance < self.radius:
            # Damage based on distance (closer = more damage)
            damage_factor = 1.0 - (distance / self.radius)
            damage = self.damage_per_second * dt * damage_factor
            robot.health -= damage
            return damage
        return 0.0

@dataclass
class Projectile:
    position: Vector2D
    velocity: Vector2D
    damage: float
    owner_id: int
    team: int
    radius: float = 5.0
    lifetime: float = 5.0
    time_alive: float = 0.0
    splash_radius: float = 0.0

    def update(self, dt):
        self.position += self.velocity * dt
        self.time_alive += dt
        return self.time_alive >= self.lifetime

@dataclass
class GameState:
    game_mode: GameMode
    teams: List[Dict]  # Team info including name, score, etc.
    robots: List[Robot]
    objectives: List[Objective]
    power_ups: List[PowerUp]
    hazards: List[Hazard]
    projectiles: List[Projectile]
    time_elapsed: float = 0.0
    round_start_time: float = 0.0
    winner: Optional[int] = None
    bases: Dict[int, Vector2D]  # Base positions for each team
    flag_position: Optional[Vector2D] = None
    payload_position: Optional[Vector2D] = None
    flag_carrier_id: Optional[int] = None  # ID of robot carrying flag

    def __post_init__(self):
        if not self.bases:
            self.bases = {}
        if self.flag_position is None:
            self.flag_position = Vector2D(SCREEN_WIDTH/2, SCREEN_HEIGHT/2)

    def get_allies(self, team_id: int) -> List[Robot]:
        return [robot for robot in self.robots if robot.team == team_id and robot.is_alive]

    def get_enemies(self, team_id: int) -> List[Robot]:
        return [robot for robot in self.robots if robot.team != team_id and robot.is_alive]

    def get_team_score(self, team_id: int) -> int:
        for team in self.teams:
            if team['id'] == team_id:
                return team['score']
        return 0

    def update(self, dt):
        self.time_elapsed += dt

        # Update robots
        for robot in self.robots:
            if robot.is_alive:
                robot.update(dt)

        # Update objectives
        for obj in self.objectives:
            obj.update(dt, self)

        # Update power-ups
        for power_up in self.power_ups:
            power_up.update(dt)

        # Update hazards
        for hazard in self.hazards:
            hazard.update(dt)

        # Update projectiles
        for projectile in self.projectiles[:]:  # Copy list to safely modify
            if projectile.update(dt):
                self.projectiles.remove(projectile)
                continue

            # Check for collisions with robots
            for robot in self.robots:
                if robot.is_alive and robot.id != projectile.owner_id and robot.team != projectile.team:
                    if robot.position.distance_to(projectile.position) < robot.vision_range * 0.1 + projectile.radius:
                        # Apply damage
                        damage = projectile.damage
                        if robot.armor > 0:
                            damage *= (1.0 - robot.armor / 100.0)
                        robot.health -= damage

                        # Create explosion effect if splash
                        if projectile.splash_radius > 0:
                            for other_robot in self.robots:
                                if other_robot.is_alive and other_robot.id != projectile.owner_id and other_robot.team != projectile.team:
                                    dist = robot.position.distance_to(other_robot.position)
                                    if dist < projectile.splash_radius:
                                        splash_damage = damage * (1.0 - dist / projectile.splash_radius)
                                        other_robot.health -= splash_damage

                        # Remove projectile after hit
                        if robot in self.robots:  # Double check robot still exists
                            self.projectiles.remove(projectile)
                        break

        # Check for flag carrier
        if self.game_mode == GameMode.FLAG_CAPTURE:
            for robot in self.robots:
                if robot.is_alive and robot.position.distance_to(self.flag_position) < 40:
                    if not self.flag_carrier_id:
                        self.flag_carrier_id = robot.id
                    elif self.flag_carrier_id == robot.id:
                        # Robot is carrying flag - check if they reach enemy base
                        enemy_base = self.bases[1 if robot.team == 0 else 0]
                        if robot.position.distance_to(enemy_base) < 100:
                            # Flag captured!
                            self.teams[robot.team]['score'] += 10
                            self.flag_carrier_id = None
                            # Reset flag position
                            self.flag_position = Vector2D(SCREEN_WIDTH/2, SCREEN_HEIGHT/2)
                            # Give a team score bonus
                            self.teams[robot.team]['score'] += 5  # Bonus for capture
                            break

            # If flag carrier died, drop the flag
            if self.flag_carrier_id:
                carrier = next((r for r in self.robots if r.id == self.flag_carrier_id), None)
                if not carrier or not carrier.is_alive:
                    self.flag_carrier_id = None
                    # Flag drops at carrier's last position
                    if carrier:
                        self.flag_position = carrier.position

    def check_win_condition(self):
        # Check for win conditions based on game mode
        if self.game_mode == GameMode.FLAG_CAPTURE:
            for team in self.teams:
                if team['score'] >= 3:  # First to 3 captures wins
                    self.winner = team['id']
                    return True
        elif self.game_mode == GameMode.ESCAPE_PAYLOAD:
            # Check if payload reached destination        elif self.game_mode == GameMode.ESCORT_PAYLOAD:            if self.payload_position and self.is_payload_at_destination():
                # Find the team that was escorting
                for robot in self.robots:
                    if robot.is_alive and any("escort_payload" in obj for obj in robot.objectives):
                        self.winner = robot.team
                        return True
        elif self.game_mode == GameMode.BASE_DEFENSE:
            # Check if a base has been destroyed
            for team_id, base_pos in self.bases.items():
                # Check if any enemy robot is close to base and base health is low
                enemies = self.get_enemies(team_id)
                for enemy in enemies:
                    if enemy.position.distance_to(base_pos) < 80:
                        # Base is under attack
                        pass  # Base health logic would go here in a more advanced version

        # If all robots of one team are dead
        for team_id in range(MAX_TEAMS):
            allies = self.get_allies(team_id)
            enemies = self.get_enemies(team_id)
            if len(allies) == 0 and len(enemies) > 0:
                self.winner = enemies[0].team  # Last team standing wins
                return True
            elif len(enemies) == 0 and len(allies) > 0:
                self.winner = team_id
                return True

        return False

    def is_payload_at_destination(self):
        if not self.payload_position or not self.bases:
            return False
        # Define destination for payload (based on team)
        destination = Vector2D(SCREEN_WIDTH * 0.9, SCREEN_HEIGHT * 0.5)
        return self.payload_position.distance_to(destination) < 50

