# AI BEHAVIOR SYSTEM
# ======================

class AIBehaviorTree:
    """A simple behavior tree for robot AI decisions"""

    def __init__(self, robot: Robot, game_state: GameState):
        self.robot = robot
        self.game_state = game_state
        self.root = self.build_behavior_tree()

    def build_behavior_tree(self):
        """Builds a simple behavior tree with priority-based nodes"""

        # Leaf nodes
        def idle():
            return "idle"

        def attack():
            return "attack"

        def retreat():
            return "retreat"

        def defend_base():
            return "defend_base"

        def capture_flag():
            return "capture_flag"

        def explore():
            return "explore"

        def heal():
            return "heal"

        def report_enemy():
            return "report_enemy"

        # Composite nodes
        def selector(*children):
            """Returns the first child that succeeds"""
            def execute():
                for child in children:
                    result = child()
                    if result:
                        return result
                return "idle"
            return execute

        def sequence(*children):
            """Returns the result of all children in sequence"""
            def execute():
                for child in children:
                    result = child()
                    if not result:
                        return "idle"
                return children[-1]()
            return execute

        def condition(condition_func, action_func):
            """Calls action_func if condition_func returns True"""
            def execute():
                if condition_func():
                    return action_func()
                return None
            return execute

        # Build the tree based on robot role
        if self.robot.role == RobotRole.ATTACKER:
            # High priority: Attack if enemy nearby and weapon ready
            # Then: Move to enemy if enemy nearby
            # Then: Explore
            return selector(
                condition(
                    lambda: self.robot.find_nearest_target(self.game_state.get_enemies(self.robot.team)) is not None and self.robot.weapon.can_fire(),
                    attack
                ),
                condition(
                    lambda: self.robot.find_nearest_target(self.game_state.get_enemies(self.robot.team)) is not None,
                    lambda: "move_to_enemy"
                ),
                explore
            )

        elif self.robot.role == RobotRole.DEFENDER:
            return selector(
                condition(
                    lambda: any(enemy.position.distance_to(self.game_state.bases[self.robot.team]) < 150 
                            for enemy in self.game_state.get_enemies(self.robot.team)),
                    defend_base
                ),
                condition(
                    lambda: self.robot.find_nearest_target(self.game_state.get_enemies(self.robot.team)) is not None,
                    lambda: "engage"
                ),
                lambda: "patrol_base"
            )

        elif self.robot.role == RobotRole.SUPPORT:
            return selector(
                condition(
                    lambda: self.robot.health < self.robot.max_health * 0.5,
                    heal
                ),
                condition(
                    lambda: any(ally.health < ally.max_health * 0.3 
                            for ally in self.game_state.get_allies(self.robot.team)),
                    lambda: "heal_allied"
                ),
                condition(
                    lambda: self.robot.find_nearest_target(self.game_state.get_enemies(self.robot.team)) is not None,
                    lambda: "support_attack"
                ),
                explore
            )

        elif self.robot.role == RobotRole.SCOUT:
            return selector(
                condition(
                    lambda: self.robot.find_nearest_target(self.game_state.get_enemies(self.robot.team)) is not None,
                    report_enemy
                ),
                explore
            )

        return idle

    def evaluate(self):
        """Evaluate the behavior tree and return the chosen action"""
        return self.root()

class AdaptiveDifficulty:
    """Manages adaptive difficulty based on team performance"""

    def __init__(self, game_state: GameState):
        self.game_state = game_state
        self.difficulty_level = 1.0  # 0.0 to 3.0
        self.performance_history = deque(maxlen=10)  # Last 10 battles
        self.last_update_time = time.time()
        self.update_cooldown = 15.0  # Update every 15 seconds

    def update(self):
        """Update difficulty based on recent performance"""
        current_time = time.time()
        if current_time - self.last_update_time < self.update_cooldown:
            return

        # Calculate team performance metrics
        team_scores = {}
        team_kills = {}
        team_objectives = {}

        for team in self.game_state.teams:
            team_id = team['id']
            team_scores[team_id] = team['score']
            team_kills[team_id] = 0
            team_objectives[team_id] = 0

        # Count kills and objectives completed
        for robot in self.game_state.robots:
            if not robot.is_alive:
                # Count this as a kill for the opposing team
                if hasattr(robot, 'last_killed_by'):
                    killer_team = robot.last_killed_by
                    if killer_team in team_kills:
                        team_kills[killer_team] += 1
            else:
                # Count objectives completed by this team
                for obj in robot.objectives:
                    if any(obj_name in obj for obj_name in ["capture_flag", "escort_payload", "defend_base"]):
                        team_objectives[robot.team] += 1

        # Calculate performance score for each team
        performance_scores = {}
        for team_id in team_scores.keys():
            score = team_scores[team_id] * 2 + team_kills[team_id] + team_objectives[team_id] * 5
            performance_scores[team_id] = score

        # Determine average performance
        if len(performance_scores) > 0:
            avg_performance = sum(performance_scores.values()) / len(performance_scores)
            max_performance = max(performance_scores.values())
            min_performance = min(performance_scores.values())

            # Adjust difficulty based on imbalance
            performance_diff = max_performance - min_performance
            if performance_diff > 20:
                # Large imbalance - increase difficulty for winning team
                winning_team = max(performance_scores, key=performance_scores.get)
                # Increase difficulty for winning team
                self.difficulty_level = min(3.0, self.difficulty_level + 0.1)
            elif performance_diff < 5 and avg_performance > 10:
                # Balanced and high performance - increase difficulty
                self.difficulty_level = min(3.0, self.difficulty_level + 0.05)
            elif avg_performance < 5:
                # Poor performance - decrease difficulty
                self.difficulty_level = max(0.5, self.difficulty_level - 0.1)

        # Store performance for learning
        self.performance_history.append({
            'time': current_time,
            'performance_scores': performance_scores,
            'difficulty': self.difficulty_level,
            'avg_performance': avg_performance
        })

        self.last_update_time = current_time

    def get_adjusted_parameters(self, team_id: int) -> Dict:
        """Return adjusted AI parameters based on difficulty and team performance"""
        # Get baseline parameters
        baseline = {
            'ai_reaction_time': 0.3,  # seconds
            'ai_accuracy': 0.7,       # 0.0 to 1.0
            'ai_aggressiveness': 0.5, # 0.0 to 1.0
            'ai_teamwork': 0.5,       # 0.0 to 1.0
            'health_multiplier': 1.0,
            'damage_multiplier': 1.0,
            'speed_multiplier': 1.0
        }

        # Adjust based on difficulty level
        difficulty_factor = self.difficulty_level / 3.0  # Normalize 0-1

        # Adjust based on team performance (better teams get harder opponents)
        team_performance = 0
        for team in self.game_state.teams:
            if team['id'] == team_id:
                team_performance = team['score']

        # Higher performance teams face harder opponents
        team_performance_factor = max(0, min(1.0, team_performance / 30.0))

        # Apply adjustments
        adjusted = baseline.copy()
        adjusted['ai_reaction_time'] = max(0.1, baseline['ai_reaction_time'] - (difficulty_factor * 0.2))
        adjusted['ai_accuracy'] = min(1.0, baseline['ai_accuracy'] + (difficulty_factor * 0.3))
        adjusted['ai_aggressiveness'] = min(1.0, baseline['ai_aggressiveness'] + (difficulty_factor * 0.3))
        adjusted['ai_teamwork'] = min(1.0, baseline['ai_teamwork'] + (difficulty_factor * 0.2))
        adjusted['health_multiplier'] = 1.0 + (difficulty_factor * 0.5)
        adjusted['damage_multiplier'] = 1.0 + (difficulty_factor * 0.4)
        adjusted['speed_multiplier'] = 1.0 + (difficulty_factor * 0.2)

        # Apply team performance adjustment
        if team_performance > 20:  # High-performing team
            adjusted['ai_accuracy'] *= (1.0 + team_performance_factor * 0.2)
            adjusted['ai_aggressiveness'] *= (1.0 + team_performance_factor * 0.3)
            adjusted['ai_teamwork'] *= (1.0 + team_performance_factor * 0.3)

        return adjusted

