class Renderer:
    """Handles all visual and audio rendering"""

    def __init__(self, screen):
        self.screen = screen
        self.font = pygame.font.SysFont('Arial', 16)
        self.large_font = pygame.font.SysFont('Arial', 24)
        self.smaller_font = pygame.font.SysFont('Arial', 12)

        # Load sounds (placeholder - in real implementation, load actual sound files)
        self.sounds = {
            'shoot': None,
            'hit': None,
            'explosion': None,
            'powerup': None,
            'capture': None,
            'death': None
        }

        # Particle system
        self.particles = []

        # Lighting effects
        self.lighting = True
        self.light_radius = 150
        self.light_intensity = 0.5

        # Audio volume
        self.volume = 0.7

    def add_particle(self, x, y, color, size, life, velocity_x, velocity_y):
        """Add a particle to the particle system"""
        self.particles.append({
            'x': x,
            'y': y,
            'color': color,
            'size': size,
            'life': life,
            'max_life': life,
            'velocity_x': velocity_x,
