"""
Team_Collaboration_Manager - A Business Software Application for Team Collaboration

A comprehensive platform for project management, task tracking, communication, and performance analytics.
"""

import json
import csv
import os
import datetime
import threading
from enum import Enum
from typing import List, Dict, Optional, Any, Set, Tuple
from dataclasses import dataclass, field
from collections import defaultdict
import uuid


# =====================
# ENUMERATIONS AND DATA STRUCTURES
# =====================

class TaskStatus(Enum):
    NOT_STARTED = "not started"
    IN_PROGRESS = "in progress"
    COMPLETED = "completed"

class UserRole(Enum):
    MEMBER = "member"
    MANAGER = "manager"
    ADMIN = "admin"


@dataclass
class User:
    id: str = field(default_factory=lambda: str(uuid.uuid4()))
    username: str = ""
    email: str = ""
    role: UserRole = UserRole.MEMBER
    performance_metrics: Dict[str, float] = field(default_factory=dict)
    feedback: List[Dict[str, Any]] = field(default_factory=list)

    def __post_init__(self):
        if not self.performance_metrics:
            self.performance_metrics = {
                "task_completion_rate": 0.0,
                "avg_time_to_complete": 0.0,
                "total_tasks_assigned": 0,
                "total_tasks_completed": 0
            }


@dataclass
class Project:
    id: str = field(default_factory=lambda: str(uuid.uuid4()))
    name: str = ""
    description: str = ""
    start_date: datetime.date = None
    end_date: datetime.date = None
    team_members: List[str] = field(default_factory=list)  # List of user IDs
    tasks: List[str] = field(default_factory=list)  # List of task IDs

    def __post_init__(self):
        if self.start_date is None:
            self.start_date = datetime.date.today()
        if self.end_date is None:
            self.end_date = self.start_date + datetime.timedelta(days=30)


@dataclass
class Task:
    id: str = field(default_factory=lambda: str(uuid.uuid4()))
    title: str = ""
    description: str = ""
    project_id: str = ""
    assignee_id: str = ""
    status: TaskStatus = TaskStatus.NOT_STARTED
    deadline: datetime.date = None
    created_at: datetime.datetime = field(default_factory=datetime.datetime.now)
    updated_at: datetime.datetime = field(default_factory=datetime.datetime.now)
    attachments: List[str] = field(default_factory=list)  # List of file paths or URLs

    def __post_init__(self):
        if self.deadline is None:
            self.deadline = datetime.date.today() + datetime.timedelta(days=7)


@dataclass
class Message:
    id: str = field(default_factory=lambda: str(uuid.uuid4()))
    sender_id: str = ""
    recipient_id: str = ""  # Can be empty for group/project-wide messages
    project_id: str = ""  # For project-related messages
    content: str = ""
    timestamp: datetime.datetime = field(default_factory=datetime.datetime.now)
    attachments: List[str] = field(default_factory=list)
    is_system: bool = False


# =====================
# MAIN APPLICATION CLASS
# =====================

class TeamCollaborationManager:
    def __init__(self):
        self.users: Dict[str, User] = {}
        self.projects: Dict[str, Project] = {}
        self.tasks: Dict[str, Task] = {}
        self.messages: List[Message] = []
        self._lock = threading.RLock()  # For thread-safe operations

    # --- Project Management ---
    def create_project(self, name: str, description: str, start_date: datetime.date = None, end_date: datetime.date = None) -> str:
        if not name.strip():
            raise ValueError("Project name cannot be empty.")
        with self._lock:
            project = Project(name=name, description=description, start_date=start_date, end_date=end_date)
            self.projects[project.id] = project
            return project.id

    def get_project(self, project_id: str) -> Optional[Project]:
        return self.projects.get(project_id)

    def update_project(self, project_id: str, **kwargs) -> bool:
        project = self.get_project(project_id)
        if not project:
            return False
        with self._lock:
            for key, value in kwargs.items():
                if hasattr(project, key):
                    setattr(project, key, value)
            return True

    def delete_project(self, project_id: str) -> bool:
        project = self.get_project(project_id)
        if not project:
            return False
        with self._lock:
            # Remove project from user references
            for user_id in self.users:
                user = self.users[user_id]
                # We don't delete tasks here; they'll be orphaned but preserved for audit
                pass
            del self.projects[project_id]
            return True

    # --- Task Management ---
    def create_task(self, title: str, description: str, project_id: str, assignee_id: str, deadline: datetime.date = None) -> str:
        if not title.strip():
            raise ValueError("Task title cannot be empty.")
        if project_id not in self.projects:
            raise ValueError(f"Project {project_id} does not exist.")
        if assignee_id not in self.users:
            raise ValueError(f"Assignee {assignee_id} does not exist.")
        with self._lock:
            task = Task(title=title, description=description, project_id=project_id, assignee_id=assignee_id, deadline=deadline)
            self.tasks[task.id] = task
            self.projects[project_id].tasks.append(task.id)
            return task.id

    def update_task(self, task_id: str, **kwargs) -> bool:
        task = self.tasks.get(task_id)
        if not task:
            return False
        if 'assignee_id' in kwargs and kwargs['assignee_id'] not in self.users:
            raise ValueError(f"New assignee {kwargs['assignee_id']} does not exist.")
        if 'project_id' in kwargs and kwargs['project_id'] not in self.projects:
            raise ValueError(f"New project {kwargs['project_id']} does not exist.")
        with self._lock:
            for key, value in kwargs.items():
                if hasattr(task, key):
                    setattr(task, key, value)
            task.updated_at = datetime.datetime.now()
            return True

    def get_task(self, task_id: str) -> Optional[Task]:
        return self.tasks.get(task_id)

    def get_tasks_by_project(self, project_id: str) -> List[Task]:
        project = self.get_project(project_id)
        if not project:
            return []
        return [self.tasks[tid] for tid in project.tasks if tid in self.tasks]

    def get_tasks_by_user(self, user_id: str) -> List[Task]:
        return [task for task in self.tasks.values() if task.assignee_id == user_id]

    def set_task_status(self, task_id: str, status: TaskStatus) -> bool:
        task = self.get_task(task_id)
        if not task:
            return False
        with self._lock:
            task.status = status
            task.updated_at = datetime.datetime.now()
            return True

    # --- Messaging System ---
    def send_message(self, sender_id: str, content: str, recipient_id: str = "", project_id: str = "", attachments: List[str] = None) -> str:
        if sender_id not in self.users:
            raise ValueError(f"Sender {sender_id} does not exist.")
        if recipient_id and recipient_id not in self.users:
            raise ValueError(f"Recipient {recipient_id} does not exist.")
        if project_id and project_id not in self.projects:
            raise ValueError(f"Project {project_id} does not exist.")
        if attachments is None:
            attachments = []
        with self._lock:
            msg = Message(sender_id=sender_id, recipient_id=recipient_id, project_id=project_id, content=content, attachments=attachments)
            self.messages.append(msg)
            return msg.id

    def get_messages_by_project(self, project_id: str) -> List[Message]:
        return [msg for msg in self.messages if msg.project_id == project_id]

    def get_messages_by_user(self, user_id: str) -> List[Message]:
        return [msg for msg in self.messages if msg.sender_id == user_id or msg.recipient_id == user_id]

