"""
CyberArena - A Multi-Agent Futuristic Battle Arena Simulation

A dynamic, team-based AI robot combat simulation featuring:
- Real-time combat with ranged/melee weapons
- Team objectives (capture the flag, escort payloads, base defense)
- Adaptive AI difficulty based on performance
- Machine learning-based strategy adaptation
- Immersive visual/audio effects
- Power-ups and environmental hazards
- Dynamic scoring and feedback system
"""

import random
import time
import math
import heapq
import json
import threading
from enum import Enum
from typing import Dict, List, Tuple, Optional, Any, Set
from dataclasses import dataclass, field
from collections import defaultdict, deque
import numpy as np


# ======================
# ENUMERATIONS
# ======================

class Team(Enum):
    RED = "Red"
    BLUE = "Blue"
    NEUTRAL = "Neutral"


class RobotType(Enum):
    ASSAULT = "Assault"
    SUPPORT = "Support"
    STEALTH = "Stealth"
    TANK = "Tank"


class WeaponType(Enum):
    LASER_RIFLE = "Laser Rifle"
    PLASMA_CANNON = "Plasma Cannon"
    MACHINE_GUN = "Machine Gun"
    SHOTGUN = "Shotgun"
    MELEE_BLADE = "Melee Blade"
    SNIPER_RIFLE = "Sniper Rifle"
    ROCKET_LAUNCHER = "Rocket Launcher"


class ObjectiveType(Enum):
    CAPTURE_FLAG = "Capture Flag"
    ESCORT_PAYLOAD = "Escort Payload"
    DEFEND_BASE = "Defend Base"
    CONTROL_POINT = "Control Point"


class PowerUpType(Enum):
    SPEED_BOOST = "Speed Boost"
    SHIELD = "Shield"
    REGEN = "Regeneration"
    CLONE = "Clone"
    TELEPORT = "Teleport"
    DAMAGE_BOOST = "Damage Boost"


class HazardType(Enum):
    ELECTRIC_FLOOR = "Electric Floor"
    LAVA_POOL = "Lava Pool"
    MINEFIELD = "Minefield"
    GRAVITY_WELL = "Gravity Well"
    CLOUD_GAS = "Cloud Gas"


class GameState(Enum):
    PREPARING = "Preparing"
    IN_PROGRESS = "In Progress"
    PAUSED = "Paused"
    COMPLETED = "Completed"


# ======================
# DATA CLASSES
# ======================

@dataclass
class Position:
    x: float
    y: float
    z: float = 0.0

    def distance_to(self, other: 'Position') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2 + (self.z - other.z)**2)

    def __add__(self, other: 'Position') -> 'Position':
        return Position(self.x + other.x, self.y + other.y, self.z + other.z)

    def __sub__(self, other: 'Position') -> 'Position':
        return Position(self.x - other.x, self.y - other.y, self.z - other.z)

    def normalize(self) -> 'Position':
        mag = math.sqrt(self.x**2 + self.y**2 + self.z**2)
        if mag == 0:
            return Position(0, 0, 0)
        return Position(self.x/mag, self.y/mag, self.z/mag)

    def to_tuple(self) -> Tuple[float, float, float]:
        return (self.x, self.y, self.z)


@dataclass
class Weapon:
    type: WeaponType
    damage: float
    range: float
    fire_rate: float  # seconds between shots
    ammo: int
    max_ammo: int
    cooldown: float = 0.0
    is_melee: bool = False

    def can_fire(self) -> bool:
        return self.cooldown <= 0 and self.ammo > 0

    def fire(self) -> float:
        if self.can_fire():
            self.ammo -= 1
            self.cooldown = self.fire_rate
            return self.damage
        return 0.0

    def reload(self):
        self.ammo = self.max_ammo

    def update(self, delta_time: float):
        self.cooldown = max(0, self.cooldown - delta_time)


@dataclass
class Robot:
    id: str
    team: Team
    robot_type: RobotType
    position: Position
    health: float
    max_health: float
    armor: float
    speed: float
    weapons: List[Weapon]
    current_weapon_index: int = 0
    objectives: List[ObjectiveType] = field(default_factory=list)
    role: str = ""
    last_seen_enemy: Optional[Position] = None
    memory: Dict[str, Any] = field(default_factory=dict)
    state: str = "idle"  # idle, moving, attacking, defending, retreating
    is_alive: bool = True
    last_action_time: float = 0.0
    power_ups: Dict[PowerUpType, float] = field(default_factory=dict)  # powerup_type -> duration

    def get_current_weapon(self) -> Weapon:
        return self.weapons[self.current_weapon_index] if self.weapons else Weapon(WeaponType.MELEE_BLADE, 20, 1.5, 0.5, 1, 1, is_melee=True)

    def take_damage(self, damage: float) -> float:
        # Apply armor reduction
        actual_damage = damage * (1 - min(0.8, self.armor / 100))
        self.health -= actual_damage
        if self.health <= 0:
            self.is_alive = False
            self.health = 0
        return actual_damage

    def heal(self, amount: float):
        self.health = min(self.max_health, self.health + amount)

    def apply_power_up(self, power_up_type: PowerUpType, duration: float):
        self.power_ups[power_up_type] = duration
        # Apply immediate effects
        if power_up_type == PowerUpType.SPEED_BOOST:
            self.speed *= 1.5
        elif power_up_type == PowerUpType.SHIELD:
            self.armor += 30
        elif power_up_type == PowerUpType.DAMAGE_BOOST:
            for weapon in self.weapons:
                weapon.damage *= 1.3

    def update_power_ups(self, delta_time: float):
        to_remove = []
        for power_up, duration in self.power_ups.items():
            new_duration = duration - delta_time
            if new_duration <= 0:
                to_remove.append(power_up)
                # Remove effects
                if power_up == PowerUpType.SPEED_BOOST:
                    self.speed /= 1.5
                elif power_up == PowerUpType.SHIELD:
                    self.armor -= 30
                elif power_up == PowerUpType.DAMAGE_BOOST:
                    for weapon in self.weapons:
                        weapon.damage /= 1.3
            else:
                self.power_ups[power_up] = new_duration

        for power_up in to_remove:
            del self.power_ups[power_up]


@dataclass
class Objective:
