# ======================
# UTILITY FUNCTIONS
# ======================

def sigmoid(x: float) -> float:
    """Sigmoid function for smooth transitions"""
    return 1 / (1 + math.exp(-x))


def lerp(start: float, end: float, t: float) -> float:
    """Linear interpolation"""
    return start + (end - start) * t


def random_position(x_range: Tuple[float, float], y_range: Tuple[float, float], z_range: Tuple[float, float] = (0, 0)) -> Position:
    """Generate a random position within specified ranges"""
    return Position(
        random.uniform(x_range[0], x_range[1]),
        random.uniform(y_range[0], y_range[1]),
        random.uniform(z_range[0], z_range[1])
    )


def generate_robot_id() -> str:
    """Generate a unique robot ID"""
    return f"ROBOT_{random.randint(1000, 9999)}"


# ======================
# AI BEHAVIOR SYSTEM
# ======================

class AIController:
    """Handles AI decision-making for robots"""

    def __init__(self, robot: Robot, game_state: 'CyberArena'):
        self.robot = robot
        self.game_state = game_state
        self.behavior_tree = self._build_behavior_tree()
        self.strategy_memory = defaultdict(list)  # Store past successful strategies
        self.last_decision_time = 0
        self.decision_cooldown = 0.5  # seconds between decisions
        self.learning_rate = 0.1
        self.exploration_rate = 0.3  # For exploration vs exploitation

    def _build_behavior_tree(self) -> Dict[str, Any]:
        """Build a behavior tree for the robot based on its type"""
        return {
            "priority": [
                self._check_alive,
                self._check_objective_completion,
                self._check_health,
                self._check_enemies_nearby,
                self._check_power_ups,
                self._check_team_needs,
                self._patrol,
                self._default_idle
            ],
            "weights": {
                "capture_flag": 1.0,
                "defend_base": 1.0,
                "escort_payload": 1.0,
                "control_point": 1.0,
                "attack": 0.8,
                "defend": 0.7,
                "support": 0.6,
                "recon": 0.5
            }
        }

    def _check_alive(self) -> Optional[str]:
        """Check if robot is alive, if not, do nothing"""
        if not self.robot.is_alive:
            return "dead"
        return None

    def _check_health(self) -> Optional[str]:
        """Check health and decide to retreat or heal"""
        if self.robot.health / self.robot.max_health < 0.3:
            # Find nearest healing power-up or ally
            healing_items = [
                pu for pu in self.game_state.power_ups 
                if pu.type == PowerUpType.REGEN and pu.is_active
            ]
            if healing_items:
                nearest = min(healing_items, key=lambda x: self.robot.position.distance_to(x.position))
                if self.robot.position.distance_to(nearest.position) < 5.0:
                    return "heal"
                else:
                    return "retreat_to_healing"

            # If no healing items, retreat from enemies
            enemies = self.game_state.get_enemies_for_team(self.robot.team)
            if enemies:
                nearest_enemy = min(enemies, key=lambda e: self.robot.position.distance_to(e.position))
                if self.robot.position.distance_to(nearest_enemy.position) < 15.0:
                    return "retreat"

        return None

    def _check_enemies_nearby(self) -> Optional[str]:
        """Check for nearby enemies and decide to attack"""
        enemies = self.game_state.get_enemies_for_team(self.robot.team)
        if not enemies:
            return None

        nearest_enemy = min(enemies, key=lambda e: self.robot.position.distance_to(e.position))
        distance = self.robot.position.distance_to(nearest_enemy.position)

        # Check if we can attack with current weapon
        current_weapon = self.robot.get_current_weapon()
        if distance <= current_weapon.range and current_weapon.can_fire():
            self.robot.last_seen_enemy = nearest_enemy.position
            # Adjust weapon if needed for optimal engagement
            if current_weapon.is_melee and distance > 2.0:
                # Switch to ranged weapon if available
                for i, weapon in enumerate(self.robot.weapons):
                    if not weapon.is_melee and weapon.range >= distance and weapon.can_fire():
                        self.robot.current_weapon_index = i
                        break

            return "attack"

        # If enemy is too far for current weapon, try to reposition
        if distance > current_weapon.range * 1.5:
            return "reposition"

        # If enemy within range but weapon on cooldown, move closer
        if distance <= current_weapon.range * 0.8:
            return "approach"

        return None

    def _check_power_ups(self) -> Optional[str]:
        """Check for nearby power-ups"""
        active_powerups = [pu for pu in self.game_state.power_ups if pu.is_active]
        if not active_powerups:
            return None

        nearest_powerup = min(active_powerups, key=lambda x: self.robot.position.distance_to(x.position))
        distance = self.robot.position.distance_to(nearest_powerup.position)

        # Only go for power-ups if they're beneficial and not too far
        if distance < 8.0:
            # Prioritize certain power-ups based on robot type
            if nearest_powerup.type == PowerUpType.SPEED_BOOST and self.robot.robot_type == RobotType.STEALTH:
                return "grab_speed_boost"
            elif nearest_powerup.type == PowerUpType.SHIELD and self.robot.health < self.robot.max_health * 0.7:
                return "grab_shield"
            elif nearest_powerup.type == PowerUpType.DAMAGE_BOOST and self.robot.robot_type == RobotType.ASSAULT:
                return "grab_damage_boost"
            elif nearest_powerup.type == PowerUpType.REGEN and self.robot.health < self.robot.max_health * 0.6:
                return "grab_regen"
            elif nearest_powerup.type == PowerUpType.TELEPORT and self.robot.robot_type == RobotType.STEALTH:
                return "grab_teleport"
            elif distance < 3.0:
                return "grab_powerup"

        return None

    def _check_team_needs(self) -> Optional[str]:
        """Assess team needs and adapt role"""
        # Get team members and their status
        team_members = self.game_state.get_teammates_for_team(self.robot.team)
        alive_team_members = [m for m in team_members if m.is_alive]

        if len(alive_team_members) == 0:
            return "go_to_base"

        # Find what roles are missing in the team
        roles = defaultdict(int)
        for member in alive_team_members:
            roles[member.role] += 1

        # Check for objectives that need attention
        objectives = self.game_state.objectives
        for obj in objectives:
            if obj.type == ObjectiveType.CAPTURE_FLAG and not obj.captured_by:
                if obj.capture_progress < 1.0 and obj.capture_progress > 0:
                    # Someone is capturing, support them
                    if self.robot.position.distance_to(obj.position) < 10.0:
                        return "support_capture"

        # If we're the only one left, go to defense
        if len(alive_team_members) == 1:
            base_positions = self.game_state.get_base_positions(self.robot.team)
            if base_positions:
                return "defend_base"

        # If there are enemies near our base, defend
        for obj in objectives:
            if obj.type == ObjectiveType.DEFEND_BASE and obj.team == self.robot.team and obj.is_active:
                if self.robot.position.distance_to(obj.position) < 20.0:
                    enemies_near_base = [
                        e for e in self.game_state.get_enemies_for_team(self.robot.team)
                        if e.position.distance_to(obj.position) < 15.0
                    ]
                    if enemies_near_base:
                        return "defend_base"

        return None

    def _check_objective_completion(self) -> Optional[str]:
        """Check if we're close to completing an objective"""
        objectives = self.game_state.objectives
        for obj in objectives:
            if obj.is_active:
                # Check if we're assigned to this objective
                if obj.type in self.robot.objectives:
                    distance = self.robot.position.distance_to(obj.position)

                    if obj.type == ObjectiveType.CAPTURE_FLAG and obj.captured_by != self.robot.team:
                        if distance < 3.0 and obj.capture_progress < 1.0:
                            return "capture_flag"
                        elif distance < 10.0:
                            return "move_to_capture_flag"

                    elif obj.type == ObjectiveType.ESCAPE_PAYLOAD and obj.payload_carrier:
                        # If we're not the carrier, escort
                        if obj.payload_carrier != self.robot.id:
                            if distance < 15.0:
                                return "escort_payload"
                        # If we're the carrier, move toward destination
                        else:
                            if obj.payload_destination and distance > 3.0:
                                return "move_to_payload_destination"

                    elif obj.type == ObjectiveType.DEFEND_BASE and obj.team == self.robot.team:
                        if distance < 10.0:
                            return "defend_base"

                    elif obj.type == ObjectiveType.CONTROL_POINT:
                        if distance < 5.0 and obj.captured_by != self.robot.team:
                            return "capture_control_point"
                        elif distance < 15.0:
                            return "move_to_control_point"

        return None

    def _patrol(self) -> Optional[str]:
        """Patrol a designated area"""
        # Get patrol points for this robot's team
        patrol_points = self.game_state.get_patrol_points(self.robot.team)
        if patrol_points:
            # Find nearest patrol point
            nearest_point = min(patrol_points, key=lambda p: self.robot.position.distance_to(p))
            if self.robot.position.distance_to(nearest_point) < 2.0:
                # Move to next point
                current_index = patrol_points.index(nearest_point)
                next_index = (current_index + 1) % len(patrol_points)
                target = patrol_points[next_index]
                return f"patrol_to_{next_index}"
            else:
                return "patrol_to_nearest"
        return None

    def _default_idle(self) -> str:
        """Default behavior when no other condition applies"""
        return "idle"

    def decide_action(self) -> str:
        """Decide the next action based on behavior tree and learning"""
        current_time = time.time()
        if current_time - self.last_decision_time < self.decision_cooldown:
            return self.robot.state  # Use last decision

        self.last_decision_time = current_time

        # Check behavior tree in priority order
        for check in self.behavior_tree["priority"]:
            result = check()
            if result is not None:
                return result

        return "idle"

    def update_strategy(self, outcome: str, actions_taken: List[str]):
        """Learn from previous battles and adapt strategy"""
        # Store recent actions and outcomes
        self.strategy_memory[outcome].append(actions_taken)

        # For learning, apply a simple reinforcement mechanism
        # This is a simplified version of Q-learning
        if len(self.strategy_memory[outcome]) > 10:
            # Trim to keep memory manageable
            self.strategy_memory[outcome] = self.strategy_memory[outcome][-10:]

        # Adjust exploration rate based on performance
        if outcome == "win":
            self.exploration_rate *= 0.95  # Less exploration if winning
        elif outcome == "loss":
            self.exploration_rate *= 1.05  # More exploration if losing
        self.exploration_rate = min(max(self.exploration_rate, 0.1), 0.8)


# ======================
# GAME ENGINE
# ======================

class CyberArena:
    """Main game engine for CyberArena"""

    def __init__(self, num_robots_per_team: int = 4, map_size: Tuple[float, float] = (100, 100)):
        self.num_robots_per_team = num_robots_per_team
        self.map_size = map_size
        self.state = GameState.PREPARING
        self.time_elapsed = 0.0
        self.delta_time = 1.0 / 60.0  # 60 FPS target
        self.last_update_time = 0.0

        # Game objects
        self.robots: List[Robot] = []
        self.objectives: List[Objective] = []
        self.power_ups: List[PowerUp] = []
        self.hazards: List[Hazard] = []
        self.scoreboard: GameStats = GameStats()

        # AI controllers
        self.ai_controllers: Dict[str, AIController] = {}

        # Game settings
        self.difficulty = "medium"  # easy, medium, hard
        self.max_game_duration = 300.0  # 5 minutes

        # Visual/audio system simulation
        self.lighting_intensity = 0.7
        self.particle_effects: List[Dict] = []
        self.sound_effects: deque = deque(maxlen=100)

        # Initialize the game
        self._initialize_game()

    def _initialize_game(self):
        """Initialize the game world with robots, objectives, and environmental elements"""
        # Create teams
        teams = [Team.RED, Team.BLUE]

        # Create robots
        robot_types = [RobotType.ASSAULT, RobotType.SUPPORT, RobotType.STEALTH, RobotType.TANK]

        for team in teams:
            for i in range(self.num_robots_per_team):
                robot_id = generate_robot_id()
                robot_type = random.choice(robot_types)

                # Position robots on their team's side
                x_range = (20, 40) if team == Team.RED else (60, 80)
                y_range = (20, 80)

                position = random_position(x_range, y_range)

                # Define stats based on robot type
                health = {
                    RobotType.ASSAULT: 120,
                    RobotType.SUPPORT: 90,
                    RobotType.STEALTH: 80,
                    RobotType.TANK: 180
                }[robot_type]

                max_health = health
                armor = {
                    RobotType.ASSAULT: 20,
                    RobotType.SUPPORT: 10,
                    RobotType.STEALTH: 5,
                    RobotType.TANK: 50
                }[robot_type]

                speed = {
                    RobotType.ASSAULT: 5.0,
                    RobotType.SUPPORT: 4.5,
                    RobotType.STEALTH: 6.5,
                    RobotType.TANK: 3.0
                }[robot_type]

                # Define weapons based on robot type
                weapons = []
                if robot_type == RobotType.ASSAULT:
                    weapons = [
                        Weapon(WeaponType.LASER_RIFLE, 25, 50.0, 0.5, 30, 30),
                        Weapon(WeaponType.SHOTGUN, 40, 15.0, 1.5, 8, 8),
                        Weapon(WeaponType.MELEE_BLADE, 50, 2.0, 0.8, 1, 1, is_melee=True)
                    ]
                elif robot_type == RobotType.SUPPORT:
                    weapons = [
                        Weapon(WeaponType.MACHINE_GUN, 15, 40.0, 0.2, 60, 60),
                        Weapon(WeaponType.LASER_RIFLE, 20, 45.0, 0.6, 25, 25),
                        Weapon(WeaponType.MELEE_BLADE, 30, 1.5, 1.0, 1, 1, is_melee=True)
                    ]
                elif robot_type == RobotType.STEALTH:
                    weapons = [
                        Weapon(WeaponType.SNIPER_RIFLE, 80, 100.0, 2.0, 12, 12),
                        Weapon(WeaponType.MELEE_BLADE, 60, 1.5, 0.7, 1, 1, is_melee=True)
                    ]
                else:  # TANK
                    weapons = [
                        Weapon(WeaponType.ROCKET_LAUNCHER, 70, 70.0, 2.5, 6, 6),
                        Weapon(WeaponType.PLASMA_CANNON, 45, 40.0, 1.0, 20, 20),
                        Weapon(WeaponType.MELEE_BLADE, 80, 2.0, 0.5, 1, 1, is_melee=True)
                    ]

                # Create robot
                robot = Robot(
                    id=robot_id,
                    team=team,
                    robot_type=robot_type,
                    position=position,
                    health=health,
                    max_health=max_health,
                    armor=armor,
                    speed=speed,
                    weapons=weapons,
                    role=self._assign_role(robot_type),
                    objectives=self._assign_objectives(robot_type, team)
                )

                self.robots.append(robot)
                self.ai_controllers[robot_id] = AIController(robot, self)

        # Create objectives
        self._create_objectives()

        # Create power-ups
        self._create_power_ups()

        # Create hazards
        self._create_hazards()

        # Initialize learning model
        self._initialize_learning_model()

    def _assign_role(self, robot_type: RobotType) -> str:
        """Assign a role based on robot type"""
        role_mapping = {
            RobotType.ASSAULT: "offensive",
            RobotType.SUPPORT: "support",
            RobotType.STEALTH: "recon",
            RobotType.TANK: "defensive"
        }
        return role_mapping[robot_type]

    def _assign_objectives(self, robot_type: RobotType, team: Team) -> List[ObjectiveType]:
        """Assign initial objectives based on robot type"""
        # Assign objectives that match the robot's role
        if robot_type == RobotType.ASSAULT:
            return [ObjectiveType.CAPTURE_FLAG, ObjectiveType.CONTROL_POINT]
        elif robot_type == RobotType.SUPPORT:
            return [ObjectiveType.ESCAPE_PAYLOAD, ObjectiveType.DEFEND_BASE]
        elif robot_type == RobotType.STEALTH:
            return [ObjectiveType.CAPTURE_FLAG, ObjectiveType.CONTROL_POINT]
        else:  # TANK
            return [ObjectiveType.DEFEND_BASE, ObjectiveType.CONTROL_POINT]

    def _create_objectives(self):
        """Create game objectives"""
        # Capture flag
        flag_pos = Position(self.map_size[0]/2, self.map_size[1]/2)
        self.objectives.append(Objective(
            type=ObjectiveType.CAPTURE_FLAG,
            position=flag_pos,
            team=Team.NEUTRAL,
            capture_progress=0.0,
            required_robots=1
        ))

        # Control point 1
        control1_pos = Position(self.map_size[0]/4, self.map_size[1]/4)
