        """Check for nearby power-ups"""
        active_powerups = [pu for pu in self.game_state.power_ups if pu.is_active]
        if not active_powerups:
            return None

        nearest_powerup = min(active_powerups, key=lambda x: self.robot.position.distance_to(x.position))
        distance = self.robot.position.distance_to(nearest_powerup.position)

        # Only go for power-ups if they're beneficial and not too far
