    assists: int = 0
    objectives_completed: int = 0
    strategy_memory: List[Dict] = field(default_factory=list)

    def take_damage(self, damage: float) -> float:
        """Apply damage to robot, considering shield first."""
        if self.shield > 0:
            shield_absorbed = min(damage, self.shield)
            self.shield -= shield_absorbed
            damage -= shield_absorbed

        if damage > 0:
            self.health -= damage
            if self.health <= 0:
                self.health = 0
                self.is_alive = False

        return damage

    def heal(self, amount: float):
        """Heal robot up to max_health."""
        self.health = min(self.max_health, self.health + amount)

    def restore_shield(self, amount: float):
        """Restore shield up to max_shield."""
        self.shield = min(self.max_shield, self.shield + amount)

    def use_energy(self, cost: float):
        """Use energy, return True if successful."""
        if self.energy >= cost:
            self.energy -= cost
            return True
        return False

    def recharge_energy(self, amount: float):
        """Recharge energy."""
        self.energy = min(self.max_energy, self.energy + amount)

    def can_attack(self) -> bool:
        """Check if robot is ready to attack."""
        return self.cooldown <= 0 and self.is_alive and self.energy > 0

    def update_cooldown(self, delta_time: float):
        """Update weapon cooldown."""
        if self.cooldown > 0:
            self.cooldown -= delta_time
            if self.cooldown < 0:
                self.cooldown = 0

    def get_aim_vector(self, target_pos: Vector2D) -> Vector2D:
        """Calculate direction vector to target."""
        return (target_pos - self.position).normalize()

    def move_towards(self, target_pos: Vector2D, delta_time: float):
        """Move robot towards target position."""
        if not self.is_alive:
            return

        direction = (target_pos - self.position).normalize()
        self.velocity = direction * self.speed
        self.position += self.velocity * delta_time

    def update(self, delta_time: float, objectives: List['Objective']):
        """Update robot state."""
        self.update_cooldown(delta_time)

        # Energy regeneration
        if self.energy < self.max_energy:
            self.recharge_energy(delta_time * 2.0)  # Regenerate 2 energy per second

        # Update strategy based on experience
        self._adapt_strategy(delta_time, objectives)

    def _adapt_strategy(self, delta_time: float, objectives: List['Objective']):
        """Adapt strategy based on experience and team performance."""
        # Every 5 seconds, analyze recent performance and adjust role
        if self.experience > 0 and time.time() - self.last_action_time > 5:
            # Simple strategy adaptation: if doing well, become more aggressive
            if self.kills > 3 and self.objectives_completed > 1:
                if self.robot_type == RobotType.SUPPORT:
                    self.robot_type = RobotType.ASSAULT
                    self.speed *= 1.1
                    self.max_health *= 1.1
                    self.weapon = WeaponType.PLASMA_CANNON
                elif self.robot_type == RobotType.SCAT:
                    self.robot_type = RobotType.ASSAULT
                    self.sight_range *= 1.2
                    self.weapon = WeaponType.SNIPER_RIFLE
            elif self.assists > 5 and self.kills < 2:
                if self.robot_type == RobotType.ASSAULT:
                    self.robot_type = RobotType.SUPPORT
                    self.max_shield *= 1.2
                    self.weapon = WeaponType.SHOTGUN

            self.last_action_time = time.time()

