@dataclass
class Objective:
    id: str
    type: ObjectiveType
    position: Vector2D
    team: Team
    progress: float = 0.0
    max_progress: float = 100.0
    captured_by: Optional[Team] = None
    is_active: bool = True
    radius: float = 40.0
    points: int = 100
    description: str = ""

    def update(self, robots: List[Robot], delta_time: float):
        """Update objective progress based on nearby robots."""
        if not self.is_active:
            return

        # Count robots from each team in proximity
        allied_count = 0
        enemy_count = 0

        for robot in robots:
            if not robot.is_alive:
                continue
            if robot.position.distance_to(self.position) <= self.radius:
                if robot.team == self.team:
                    allied_count += 1
                else:
                    enemy_count += 1

        # Progress logic based on team presence
        if allied_count > 0 and enemy_count == 0:
            # Allied team is controlling
            self.progress += allied_count * delta_time * 3.0
            if self.captured_by != self.team:
                self.captured_by = self.team
                # Visual/audio feedback for capture
                self._notify_capture()
        elif enemy_count > 0 and allied_count == 0:
            # Enemy team is controlling
            self.progress -= enemy_count * delta_time * 2.0
            if self.captured_by != self.team.opposite():
                self.captured_by = self.team.opposite()
                # Visual/audio feedback for capture
                self._notify_capture()
        elif allied_count > 0 and enemy_count > 0:
            # Contesting - slower progress
            if self.captured_by == self.team:
                self.progress -= enemy_count * delta_time
            elif self.captured_by == self.team.opposite():
                self.progress += allied_count * delta_time
            else:
                # Neutral, let whoever has more influence
                if allied_count > enemy_count:
                    self.progress += (allied_count - enemy_count) * delta_time
                else:
                    self.progress -= (enemy_count - allied_count) * delta_time

        # Clamp progress
        self.progress = max(0, min(self.max_progress, self.progress))

        # Check if objective completed
        if self.progress >= self.max_progress and self.captured_by is not None:
            self._complete_objective()

    def opposite(self) -> Team:
        """Return opposite team."""
        if self.team == Team.RED:
            return Team.BLUE
        elif self.team == Team.BLUE:
            return Team.RED
        else:
            return Team.NEUTRAL

    def _notify_capture(self):
        """Notify of capture (in actual implementation, this would trigger audio/visual effects)."""
        # Placeholder for sound and visual feedback
        pass

    def _complete_objective(self):
        """Handle objective completion."""
        self.is_active = False
        # This would trigger game events like scoring, next objective, etc.
        pass

