@dataclass
class Hazard:
    type: HazardType
    position: Vector2D
    damage_per_second: float
    radius: float
    active: bool = True
    duration: float = 0.0
    spawn_time: float = 0.0

    def update(self, robots: List[Robot], delta_time: float) -> List[Robot]:
        """Update hazard and check for damage to robots."""
        if not self.active:
            return []

        damaged_robots = []

        # Apply damage to robots in range
        for robot in robots:
            if not robot.is_alive:
                continue
            if robot.position.distance_to(self.position) <= self.radius:
                robot.take_damage(self.damage_per_second * delta_time)
                damaged_robots.append(robot)

        # Auto-despawn after duration
        if self.spawn_time > 0 and time.time() - self.spawn_time > self.duration:
            self.active = False

        return damaged_robots

@dataclass
class GameState:
    """Current state of the game."""
    time: float = 0.0
    round_time: float = 300.0  # 5 minute rounds
    objectives: List[Objective] = field(default_factory=list)
    robots: List[Robot] = field(default_factory=list)
    projectiles: List[Projectile] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    score: Dict[Team, int] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    winner: Optional[Team] = None
    round_active: bool = True
    last_spawn_time: float = 0.0
    difficulty_level: float = 1.0  # 1.0 = normal, >1.0 = harder, <1.0 = easier

    def update(self, delta_time: float):
        """Update all game components."""
        self.time += delta_time

        # Update objectives
        for obj in self.objectives:
            obj.update(self.robots, delta_time)

        # Update projectiles
        self.projectiles = [p for p in self.projectiles if p.update(delta_time)]

        # Update power-ups
        for power_up in self.power_ups:
            collected = power_up.update(self.robots, delta_time)
            # Award points for power-up collection (simplified)
            for robot in collected:
                self.score[robot.team] += 10

        # Update hazards
        for hazard in self.hazards:
            hazard.update(self.robots, delta_time)

        # Update robots
        for robot in self.robots:
            if robot.is_alive:
                robot.update(delta_time, self.objectives)

        # Check for round completion
        if self.time >= self.round_time:
            self.round_active = False
            # Determine winner based on scores
            if self.score[Team.RED] > self.score[Team.BLUE]:
                self.winner = Team.RED
            elif self.score[Team.BLUE] > self.score[Team.RED]:
                self.winner = Team.BLUE
            else:
                self.winner = Team.NEUTRAL  # Tie

        # Spawn new objectives or power-ups based on game state and difficulty
        self._spawn_dynamic_elements(delta_time)

    def _spawn_dynamic_elements(self, delta_time: float):
        """Spawn dynamic elements based on game state and difficulty."""
        # Spawn power-ups based on game difficulty and time
        if time.time() - self.last_spawn_time > 15 * self.difficulty_level:
            # Randomly choose a power-up type
            power_up_types = list(PowerUpType)
            chosen_type = random.choice(power_up_types)

            # Ensure spawn is not too close to existing objects
            spawn_pos = Vector2D(
                random.uniform(50, 750),
                random.uniform(50, 550)
            )

            # Default values based on type
            values = {
                PowerUpType.HEALTH_PACK: 30,
                PowerUpType.SHIELD_BOOST: 20,
                PowerUpType.SPEED_BOOST: 1.2,
                PowerUpType.DAMAGE_BOOST: 1.1,
                PowerUpType.REGEN: 15,
                PowerUpType.TELEPORT: 1.0
            }

            new_power_up = PowerUp(
                type=chosen_type,
                position=spawn_pos,
                value=values.get(chosen_type, 20),
                spawn_time=time.time()
            )
            self.power_ups.append(new_power_up)
            self.last_spawn_time = time.time()

        # Spawn hazards based on game length and difficulty
        if self.time > 60 and random.random() < 0.01 * self.difficulty_level:
            hazard_types = list(HazardType)
            chosen_hazard = random.choice(hazard_types)

            hazard_pos = Vector2D(
                random.uniform(50, 750),
                random.uniform(50, 550)
            )

            hazard_values = {
                HazardType.LAVA_POOL: Hazard(HazardType.LAVA_POOL, hazard_pos, 5, 40, True, 20, time.time()),
                HazardType.ELECTRIC_FIELD: Hazard(HazardType.ELECTRIC_FIELD, hazard_pos, 3, 30, True, 15, time.time()),
                HazardType.MINE_FIELD: Hazard(HazardType.MINE_FIELD, hazard_pos, 2, 50, True, 25, time.time()),
                HazardType.GRAVITY_WELL: Hazard(HazardType.GRAVITY_WELL, hazard_pos, 1, 60, True, 30, time.time())
            }

            self.hazards.append(hazard_values[chosen_hazard])

@dataclass
class AdaptiveAI:
    """Adaptive AI system that adjusts robot behavior based on performance."""

    def __init__(self):
        self.performance_history = defaultdict(list)
        self.difficulty_adjustment_factor = 1.0
        self.last_adjustment_time = 0.0

    def evaluate_performance(self, game_state: GameState) -> float:
        """Evaluate team performance and return a performance score."""
        total_score = 0
        team_scores = {Team.RED: 0, Team.BLUE: 0}

        # Calculate average score per team
        for robot in game_state.robots:
            if robot.is_alive:
                team_scores[robot.team] += robot.kills * 10 + robot.assists * 5 + robot.objectives_completed * 20

        # Normalize based on team size
        red_robots_alive = sum(1 for r in game_state.robots if r.team == Team.RED and r.is_alive)
        blue_robots_alive = sum(1 for r in game_state.robots if r.team == Team.BLUE and r.is_alive)

        if red_robots_alive > 0:
            team_scores[Team.RED] /= red_robots_alive
        if blue_robots_alive > 0:
            team_scores[Team.BLUE] /= blue_robots_alive

        # Return average performance across teams
        return (team_scores[Team.RED] + team_scores[Team.BLUE]) / 2 if (red_robots_alive + blue_robots_alive) > 0 else 0

    def adjust_difficulty(self, game_state: GameState, delta_time: float) -> float:
        """Adjust difficulty based on average team performance."""
        if time.time() - self.last_adjustment_time < 30:  # Only adjust every 30 seconds
            return self.difficulty_adjustment_factor

        performance_score = self.evaluate_performance(game_state)

        # Store performance history
        self.performance_history['performance'].append(performance_score)
        if len(self.performance_history['performance']) > 10:
            self.performance_history['performance'].pop(0)

        # Calculate average performance
        avg_performance = sum(self.performance_history['performance']) / len(self.performance_history['performance']) if self.performance_history['performance'] else 0

        # Adjust difficulty based on performance
        # If performance is too high, make it harder; if too low, make it easier
        if avg_performance > 35:
            self.difficulty_adjustment_factor = min(2.0, self.difficulty_adjustment_factor + 0.05)
        elif avg_performance < 15:
            self.difficulty_adjustment_factor = max(0.5, self.difficulty_adjustment_factor - 0.05)

        self.last_adjustment_time = time.time()
        return self.difficulty_adjustment_factor

    def get_ai_strategy(self, robot: Robot, game_state: GameState) -> Dict[str, Any]:
        """Generate AI strategy based on robot's role, experience, and game state."""
        # Simple strategy selection based on role and experience
        strategies = {
            RobotType.ASSAULT: self._assault_strategy,
            RobotType.SUPPORT: self._support_strategy,
            RobotType.SCOUT: self._scout_strategy,
            RobotType.TANK: self._tank_strategy
        }

        strategy_func = strategies.get(robot.robot_type, self._default_strategy)
        return strategy_func(robot, game_state)

    def _assault_strategy(self, robot: Robot, game_state: GameState) -> Dict[str, Any]:
        """Assault robot strategy: aggressive, target enemies, capture objectives."""
        # Find nearest enemy
        nearest_enemy = self._find_nearest_target(robot, game_state, enemy_only=True)
        nearest_objective = self._find_nearest_objective(robot, game_state)

        # If enemy is close and in range, attack
        if nearest_enemy and robot.position.distance_to(nearest_enemy.position) < 100:
            return {
                'action': 'attack',
                'target': nearest_enemy.id,
                'priority': 'high'
            }
        # Otherwise, move towards objective
        elif nearest_objective and nearest_objective.captured_by != robot.team:
            return {
                'action': 'move_to_objective',
                'target': nearest_objective.id,
                'priority': 'medium'
            }
        # Otherwise, patrol or find enemies
        else:
            return {
                'action': 'patrol',
                'target': 'random',
                'priority': 'low'
            }

    def _support_strategy(self, robot: Robot, game_state: GameState) -> Dict[str, Any]:
        """Support robot strategy: heal, protect, assist teammates."""
        # Find nearest ally in need of healing
        nearest_ally_in_need = None
        min_health_ratio = float('inf')

        for ally in game_state.robots:
            if ally.team == robot.team and ally.is_alive and ally != robot:
                health_ratio = ally.health / ally.max_health
                if health_ratio < min_health_ratio and health_ratio < 0.7:
                    min_health_ratio = health_ratio
                    nearest_ally_in_need = ally

        # Find nearest objective to defend
        nearest_objective = self._find_nearest_objective(robot, game_state)

        if nearest_ally_in_need:
            return {
                'action': 'heal',
                'target': nearest_ally_in_need.id,
                'priority': 'high'
            }
        elif nearest_objective and nearest_objective.captured_by != robot.team:
            return {
                'action': 'defend_objective',
                'target': nearest_objective.id,
                'priority': 'medium'
            }
        else:
            return {
                'action': 'patrol',
                'target': 'random',
                'priority': 'low'
            }

    def _scout_strategy(self, robot: Robot, game_state: GameState) -> Dict[str, Any]:
        """Scout robot strategy: explore, spot enemies, provide intel."""
        # Find enemies at long range
        enemies = [r for r in game_state.robots if r.team != robot.team and r.is_alive]
        visible_enemies = [e for e in enemies if robot.position.distance_to(e.position) < robot.sight_range]

        if visible_enemies:
            return {
                'action': 'report',
                'target': visible_enemies[0].id,
                'priority': 'high'
            }
        else:
            # Move to unexplored areas
            return {
                'action': 'explore',
                'target': 'unexplored',
                'priority': 'medium'
            }

    def _tank_strategy(self, robot: Robot, game_state: GameState) -> Dict[str, Any]:
        """Tank robot strategy: absorb damage, protect objectives."""
        # Find nearest objective to defend
        nearest_objective = self._find_nearest_objective(robot, game_state)

        if nearest_objective and nearest_objective.captured_by == robot.team:
            return {
                'action': 'defend_objective',
                'target': nearest_objective.id,
                'priority': 'high'
            }
        else:
            # Find nearest enemy and engage
            nearest_enemy = self._find_nearest_target(robot, game_state, enemy_only=True)
            if nearest_enemy:
                return {
                    'action': 'engage',
                    'target': nearest_enemy.id,
                    'priority': 'medium'
                }
            else:
                return {
                    'action': 'patrol',
                    'target': 'random',
                    'priority': 'low'
                }

    def _default_strategy(self, robot: Robot, game_state: GameState) -> Dict[str, Any]:
        """Default fallback strategy."""
        nearest_enemy = self._find_nearest_target(robot, game_state, enemy_only=True)
        nearest_objective = self._find_nearest_objective(robot, game_state)

        if nearest_enemy and robot.position.distance_to(nearest_enemy.position) < 120:
            return {
                'action': 'attack',
                'target': nearest_enemy.id,
                'priority': 'high'
            }
        elif nearest_objective and nearest_objective.captured_by != robot.team:
            return {
                'action': 'move_to_objective',
                'target': nearest_objective.id,
                'priority': 'medium'
            }
        else:
            return {
                'action': 'patrol',
                'target': 'random',
                'priority': 'low'
            }

    def _find_nearest_target(self, robot: Robot, game_state: GameState, enemy_only: bool = False) -> Optional[Robot]:
        """Find nearest target robot."""
        targets = []
        for other in game_state.robots:
            if other.is_alive:
                if enemy_only:
                    if other.team != robot.team:
                        targets.append(other)
                else:
                    targets.append(other)

        if not targets:
            return None

        nearest = min(targets, key=lambda r: robot.position.distance_to(r.position))
        return nearest

    def _find_nearest_objective(self, robot: Robot, game_state: GameState) -> Optional[Objective]:
        """Find nearest objective."""
        if not game_state.objectives:
            return None

        nearest = min(game_state.objectives, key=lambda o: robot.position.distance_to(o.position))
        return nearest

