    strategy_memory: List[Dict[str, Any]] = field(default_factory=list)  # for learning
    role: str = "default"  # dynamic role like "attacker", "defender", "support"

    def take_damage(self, damage: float) -> float:
        """Apply damage with armor reduction"""
        effective_damage = max(0, damage - self.armor)
        self.health = max(0, self.health - effective_damage)
        if self.health <= 0:
            self.is_alive = False
        return effective_damage

    def heal(self, amount: float) -> float:
        """Heal robot by specified amount"""
        old_health = self.health
        self.health = min(self.max_health, self.health + amount)
        return self.health - old_health

    def add_ability(self, ability: 'Ability') -> None:
        """Add an ability to the robot"""
        self.abilities.append(ability)

    def can_use_ability(self, ability_name: str, current_time: float) -> bool:
        """Check if ability is ready to use"""
        if ability_name not in self.cooldowns:
            return True
        return current_time >= self.cooldowns[ability_name]

    def use_ability(self, ability_name: str, current_time: float) -> bool:
        """Use ability if on cooldown, update cooldown"""
        if not self.can_use_ability(ability_name, current_time):
            return False
        ability = next((a for a in self.abilities if a.name == ability_name), None)
        if ability:
            self.cooldowns[ability_name] = current_time + ability.cooldown
            return True
        return False

    def get_status(self) -> Dict[str, Any]:
        """Return robot status for debugging and UI"""
        return {
            "id": self.id,
            "team": self.team.value,
            "type": self.robot_type.value,
            "position": {"x": self.position.x, "y": self.position.y},
            "health": self.health,
            "max_health": self.max_health,
            "armor": self.armor,
            "speed": self.speed,
            "weapon": self.weapon.name if self.weapon else None,
            "is_alive": self.is_alive,
            "role": self.role,
            "objectives": [obj.value for obj in self.objectives],
            "abilities": [a.name for a in self.abilities],
            "cooldowns": self.cooldowns
        }

@dataclass
class Weapon:
    name: str
    weapon_type: WeaponType
    damage: float
    range: float
    fire_rate: float  # seconds between shots
    ammo: int = -1  # -1 means infinite
    max_ammo: int = -1
    reload_time: float = 2.0
    is_active: bool = True
    impact_effect: Optional[str] = None  # particle effect name

    def __post_init__(self):
        self.last_fired = 0.0
        self.current_ammo = self.max_ammo if self.max_ammo != -1 else self.ammo

    def can_fire(self, current_time: float) -> bool:
        """Check if weapon can fire"""
        if not self.is_active:
            return False
        if self.ammo == 0:
            return False
        return current_time - self.last_fired >= self.fire_rate

    def fire(self, current_time: float) -> bool:
        """Fire weapon if possible, return True if fired"""
        if not self.can_fire(current_time):
            return False

        self.last_fired = current_time
        if self.ammo > 0:
            self.ammo -= 1
        elif self.max_ammo > 0:
            self.current_ammo -= 1
            if self.current_ammo <= 0:
                self.is_active = False
        return True

    def reload(self) -> bool:
        """Reload weapon"""
        if self.max_ammo > 0 and self.current_ammo < self.max_ammo:
            self.current_ammo = self.max_ammo
            self.is_active = True
            return True
        return False

@dataclass
class Ability:
    name: str
    cooldown: float
    duration: float
    effect_type: str  # "heal", "buff", "debuff", "area_effect", "teleport", etc.
    effect_value: float
    radius: float = 0.0  # for area effects
    description: str = ""

    def apply_effect(self, target: 'Robot', current_time: float) -> Dict[str, Any]:
        """Apply ability effect to target robot"""
        result = {"success": False, "effect": self.effect_type, "value": self.effect_value}

        if self.effect_type == "heal":
            healed = target.heal(self.effect_value)
            result["healed"] = healed
            result["success"] = healed > 0

        elif self.effect_type == "buff":
            if self.name == "speed_boost":
                target.speed *= (1 + self.effect_value)
                # Store original speed for later restoration
                if not hasattr(target, "original_speed"):
                    target.original_speed = target.speed
            result["success"] = True

        elif self.effect_type == "debuff":
            if self.name == "slow":
                target.speed *= (1 - self.effect_value)
                if not hasattr(target, "original_speed"):
                    target.original_speed = target.speed
            result["success"] = True

        elif self.effect_type == "shield":
            target.armor += self.effect_value
            result["success"] = True

        elif self.effect_type == "area_effect":
            # This is handled by the arena, not individual robots
            result["success"] = True

        elif self.effect_type == "teleport":
            # Teleport is handled by arena
            result["success"] = True

        return result

@dataclass
class PowerUp:
    type: PowerUpType
    position: Vector2D
    value: float = 25.0  # default value for health, speed, etc.
    duration: float = 10.0  # duration for temporary effects
    is_active: bool = True
    spawn_time: float = 0.0

    def get_effect(self) -> Dict[str, Any]:
        """Return the power-up effect"""
        return {
            "type": self.type.value,
            "value": self.value,
            "duration": self.duration
        }

@dataclass
class Hazard:
    type: HazardType
    position: Vector2D
    radius: float
    damage_per_second: float = 10.0
    duration: float = float('inf')  # how long it lasts
    spawn_time: float = 0.0
    is_active: bool = True

    def affect_robot(self, robot: Robot, current_time: float) -> float:
        """Apply hazard damage to robot"""
        if not self.is_active:
            return 0.0
        damage = self.damage_per_second * 0.1  # damage per frame (assuming 10 FPS)
        robot.take_damage(damage)
        return damage

@dataclass
class Objective:
    type: ObjectiveType
    position: Vector2D
    radius: float
    team: Team  # which team's objective
    status: str = "neutral"  # "neutral", "captured", "defending", "escort_in_progress"
    capture_progress: float = 0.0  # 0.0 to 1.0 for capture objectives
    captured_by: Optional[Team] = None
    escort_distance: float = 0.0  # for escort objectives
    escort_target: Optional[Vector2D] = None
    team_members_near: int = 0

    def update(self, robots: List[Robot], current_time: float) -> None:
        """Update objective state based on nearby robots"""
        self.team_members_near = 0
        for robot in robots:
            if robot.team == self.team and robot.is_alive and self.position.distance_to(robot.position) <= self.radius:
                self.team_members_near += 1

        if self.type == ObjectiveType.CAPTURE_FLAG:
            # Capture logic
            nearby_enemies = 0
            for robot in robots:
                if robot.team != self.team and robot.is_alive and self.position.distance_to(robot.position) <= self.radius:
                    nearby_enemies += 1

            if self.team_members_near > 0 and nearby_enemies == 0:
                capture_rate = 0.02 * self.team_members_near
                self.capture_progress = min(1.0, self.capture_progress + capture_rate)
                if self.capture_progress >= 1.0 and not self.captured_by:
                    self.captured_by = self.team
                    self.status = "captured"
            elif self.team_members_near == 0 and self.captured_by:
                # Reset if no one is there
                self.capture_progress = 0.0
                self.captured_by = None
                if self.status == "captured":
                    self.status = "neutral"

        elif self.type == ObjectiveType.ESCORT_PAYLOAD:
            # Escort logic
            if self.captured_by is None:
                # Find robots from the escorting team to start escort
                for robot in robots:
                    if robot.team == self.team and robot.is_alive and self.position.distance_to(robot.position) <= self.radius:
                        self.captured_by = self.team
                        self.status = "escort_in_progress"
                        break
            if self.captured_by:
                # Move toward target if escorting
                if self.escort_target:
                    # Simple movement toward target
                    direction = self.escort_target - self.position
                    distance = direction.distance_to(Vector2D(0, 0))
                    if distance > 0:
                        step = direction.normalize() * 0.1
                        self.position = self.position + step
                        self.escort_distance += 0.1
                        if self.escort_distance >= 100.0:  # target reached
                            self.status = "completed"
                            self.captured_by = self.team
                    else:
                        self.status = "completed"

@dataclass
class GameState:
    """Central game state container"""
    time: float = 0.0
    round_duration: float = 300.0  # 5 minutes
    robots: List[Robot] = field(default_factory=list)
    objectives: List[Objective] = field(default_factory=list)
    power_ups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    map_size: Vector2D = field(default_factory=lambda: Vector2D(100, 100))
    scores: Dict[Team, float] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    game_status: str = "preparing"  # "preparing", "running", "ended"
    last_powerup_spawn: float = 0.0
    last_hazard_spawn: float = 0.0

    def add_robot(self, robot: Robot) -> None:
        self.robots.append(robot)

    def get_team_robots(self, team: Team) -> List[Robot]:
        return [r for r in self.robots if r.team == team and r.is_alive]

    def get_robot_by_id(self, robot_id: str) -> Optional[Robot]:
        for robot in self.robots:
            if robot.id == robot_id:
                return robot
        return None

    def get_objective_by_type(self, obj_type: ObjectiveType) -> Optional[Objective]:
        for obj in self.objectives:
            if obj.type == obj_type:
                return obj
        return None

    def get_nearest_powerup(self, position: Vector2D) -> Optional[PowerUp]:
        nearest = None
        min_dist = float('inf')
        for pu in self.power_ups:
            if pu.is_active:
                dist = position.distance_to(pu.position)
                if dist < min_dist:
                    min_dist = dist
                    nearest = pu
        return nearest

    def get_nearest_hazard(self, position: Vector2D) -> Optional[Hazard]:
        nearest = None
        min_dist = float('inf')
        for hazard in self.hazards:
            if hazard.is_active:
                dist = position.distance_to(hazard.position)
                if dist < min_dist:
                    min_dist = dist
                    nearest = hazard
        return nearest

# -----------------------------
# AI BEHAVIOR SYSTEM
# -----------------------------

class RobotAI:
    """AI system for robots to make decisions"""

    def __init__(self, game_state: GameState):
        self.game_state = game_state
        self.learning_rate = 0.1
        self.exploration_rate = 0.3
        self.strategy_history = defaultdict(list)

    def calculate_next_move(self, robot: Robot, current_time: float) -> Dict[str, Any]:
        """Calculate the best action for a robot based on current state"""
        if not robot.is_alive:
            return {"action": "idle", "target": None}

        # Get nearby robots and objectives
        allies = [r for r in self.game_state.robots if r.team == robot.team and r.is_alive]
        enemies = [r for r in self.game_state.robots if r.team != robot.team and r.is_alive]
        objectives = self.game_state.objectives
        power_ups = [pu for pu in self.game_state.power_ups if pu.is_active]
        hazards = [h for h in self.game_state.hazards if h.is_active]

        # Determine robot's role based on team composition and current situation
        robot.role = self._determine_role(robot, allies, enemies, objectives)

        # Adaptive difficulty: Modify behavior based on team performance
        self._adjust_difficulty(robot, allies, enemies)

        # Priority ordering for decision making
        actions = []

        # 1. Check if robot needs healing
        if robot.health < robot.max_health * 0.3:
            nearest_powerup = self.game_state.get_nearest_powerup(robot.position)
            if nearest_powerup and nearest_powerup.type == PowerUpType.HEALTH_PACK:
                actions.append({
                    "action": "move",
                    "target": nearest_powerup.position,
                    "priority": 5,
                    "reason": "low_health"
                })

        # 2. Check for nearby hazards
        nearest_hazard = self.game_state.get_nearest_hazard(robot.position)
        if nearest_hazard and nearest_hazard.distance_to(robot.position) < 5.0:
            # Move away from hazard
            away_direction = robot.position - nearest_hazard.position
            if away_direction.distance_to(Vector2D(0, 0)) > 0:
                escape_pos = robot.position + away_direction.normalize() * 10.0
                actions.append({
                    "action": "move",
                    "target": escape_pos,
                    "priority": 4,
                    "reason": "avoid_hazard"
                })

        # 3. Check for power-ups
        if robot.weapon and robot.weapon.current_ammo < 10 and robot.weapon.max_ammo > 0:
            nearest_powerup = self.game_state.get_nearest_powerup(robot.position)
            if nearest_powerup and nearest_powerup.type == PowerUpType.WEAPON_UPGRADE:
                actions.append({
                    "action": "move",
                    "target": nearest_powerup.position,
                    "priority": 4,
                    "reason": "low_ammo"
                })

        # 4. Check for objectives
        for obj in objectives:
            if obj.team == robot.team and obj.captured_by != robot.team:
                # Objective we need to capture or defend
                if obj.type == ObjectiveType.CAPTURE_FLAG:
                    if obj.captured_by is None:
                        # Capture objective
                        if obj.position.distance_to(robot.position) < 3.0:
                            # Use ability or attack if enemy present
                            nearby_enemies = [e for e in enemies if e.position.distance_to(obj.position) < 5.0]
                            if len(nearby_enemies) == 0:
                                actions.append({
                                    "action": "capture",
                                    "target": obj.position,
                                    "priority": 5,
                                    "reason": "capture_flag"
                                })
                            else:
                                # Attack enemies near objective
                                closest_enemy = min(nearby_enemies, key=lambda e: e.position.distance_to(robot.position))
                                actions.append({
                                    "action": "attack",
                                    "target": closest_enemy.position,
                                    "priority": 4,
                                    "reason": "clear_objective"
                                })
                        else:
                            # Move to objective
                            actions.append({
                                "action": "move",
                                "target": obj.position,
                                "priority": 3,
                                "reason": "move_to_objective"
                            })
                    elif obj.captured_by == robot.team:
                        # Defend captured objective
                        nearby_enemies = [e for e in enemies if e.position.distance_to(obj.position) < 10.0]
                        if len(nearby_enemies) > 0:
                            closest_enemy = min(nearby_enemies, key=lambda e: e.position.distance_to(robot.position))
                            actions.append({
                                "action": "attack",
                                "target": closest_enemy.position,
                                "priority": 3,
                                "reason": "defend_objective"
                            })
                        else:
                            # Patrol around objective
                            patrol_point = obj.position + Vector2D(5, 5)
                            actions.append({
                                "action": "move",
                                "target": patrol_point,
                                "priority": 2,
                                "reason": "patrol_objective"
                            })

                elif obj.type == ObjectiveType.ESCORT_PAYLOAD:
                    if obj.status == "escort_in_progress":
                        if obj.position.distance_to(robot.position) < 3.0:
                            # Protect payload
                            nearby_enemies = [e for e in enemies if e.position.distance_to(obj.position) < 8.0]
                            if len(nearby_enemies) > 0:
                                closest_enemy = min(nearby_enemies, key=lambda e: e.position.distance_to(robot.position))
                                actions.append({
                                    "action": "attack",
                                    "target": closest_enemy.position,
                                    "priority": 4,
                                    "reason": "protect_payload"
                                })
                        else:
                            # Move to payload
                            actions.append({
                                "action": "move",
                                "target": obj.position,
                                "priority": 3,
                                "reason": "escort_payload"
                            })

            elif obj.team != robot.team and obj.captured_by == obj.team:
                # Enemy objective to capture
                if obj.position.distance_to(robot.position) < 3.0:
                    # Attack enemy objective
                    nearby_enemies = [e for e in enemies if e.position.distance_to(obj.position) < 5.0]
                    if len(nearby_enemies) == 0:
                        actions.append({
                            "action": "capture",
                            "target": obj.position,
                            "priority": 4,
                            "reason": "steal_flag"
                        })
                    else:
                        # Attack closest enemy
                        closest_enemy = min(nearby_enemies, key=lambda e: e.position.distance_to(robot.position))
                        actions.append({
                            "action": "attack",
                            "target": closest_enemy.position,
                            "priority": 3,
                            "reason": "attack_enemy_objective"
                        })
                else:
                    # Move to enemy objective
                    actions.append({
                        "action": "move",
                        "target": obj.position,
                        "priority": 2,
                        "reason": "attack_enemy_objective"
                    })

        # 5. If no specific objective, find enemies to attack
        if len(actions) == 0:
            if len(enemies) > 0:
                # Find nearest enemy
                nearest_enemy = min(enemies, key=lambda e: e.position.distance_to(robot.position))
                if robot.weapon and robot.weapon.range >= robot.position.distance_to(nearest_enemy.position):
                    # Can attack
                    actions.append({
                        "action": "attack",
                        "target": nearest_enemy.position,
                        "priority": 3,
                        "reason": "attack_nearest_enemy"
                    })
                else:
                    # Move toward enemy
                    actions.append({
                        "action": "move",
                        "target": nearest_enemy.position,
                        "priority": 2,
                        "reason": "approach_enemy"
                    })
            else:
                # No enemies, patrol randomly
                patrol_pos = robot.position + Vector2D(
                    random.uniform(-5, 5), 
                    random.uniform(-5, 5)
                )
                actions.append({
                    "action": "move",
                    "target": patrol_pos,
                    "priority": 1,
                    "reason": "patrol"
                })

        # 6. Use special abilities if available
        if len(actions) > 0 and actions[0]["priority"] >= 4:
            # Try to use abilities that could help
            for ability in robot.abilities:
                if robot.can_use_ability(ability.name, current_time):
                    if ability.effect_type == "heal" and robot.health < robot.max_health * 0.5:
                        actions.append({
                            "action": "use_ability",
                            "target": robot.id,
                            "ability": ability.name,
                            "priority": 6,
                            "reason": "use_heal"
                        })
                    elif ability.effect_type == "area_effect" and len(enemies) > 1:
                        # Use area effect if multiple enemies nearby
                        nearby_enemies = [e for e in enemies if e.position.distance_to(robot.position) < ability.radius]
                        if len(nearby_enemies) >= 2:
                            actions.append({
                                "action": "use_ability",
                                "target": robot.position,
                                "ability": ability.name,
                                "priority": 5,
                                "reason": "use_area_effect"
                            })

        # Sort by priority (highest first)
        actions.sort(key=lambda x: x["priority"], reverse=True)

        # Exploration vs exploitation for learning
        if random.random() < self.exploration_rate and len(actions) > 1:
            # Randomly pick a different action for exploration
            actions[0] = actions[random.randint(1, len(actions) - 1)]

        # Record this decision for learning
        self._record_decision(robot, actions[0], current_time)

        return actions[0] if actions else {"action": "idle", "target": None}

    def _determine_role(self, robot: Robot, allies: List[Robot], enemies: List[Robot], objectives: List[Objective]) -> str:
        """Dynamically assign role based on team composition and objectives"""
        # If no teammates, default to assault
        if len(allies) == 0:
            return "assault"

        # Count how many of each type we have
        assault_count = sum(1 for a in allies if a.robot_type == RobotType.ASSAULT)
        support_count = sum(1 for a in allies if a.robot_type == RobotType.SUPPORT)
        scout_count = sum(1 for a in allies if a.robot_type == RobotType.SCOUT)
        tank_count = sum(1 for a in allies if a.robot_type == RobotType.TANK)

        # Assign roles based on team needs
        if robot.robot_type == RobotType.ASSAULT:
            # Assault robots should prioritize attack
            return "attacker"

        elif robot.robot_type == RobotType.SUPPORT:
            # Support robots should heal and buff
            if support_count > 0 and any(a.health < a.max_health * 0.4 for a in allies):
                return "healer"
            else:
                return "supporter"

        elif robot.robot_type == RobotType.SCOUT:
            # Scout robots should find objectives and enemies
            return "scout"

        elif robot.robot_type == RobotType.TANK:
            # Tank robots should protect objectives and allies
            if any(o.captured_by == robot.team for o in objectives):
                return "defender"
            else:
                return "tank"

        # Default
        return "default"

    def _adjust_difficulty(self, robot: Robot, allies: List[Robot], enemies: List[Robot]) -> None:
        """Adjust AI behavior based on performance (adaptive difficulty)"""
        team_score = self.game_state.scores[robot.team]
        enemy_score = self.game_state.scores[Team.RED if robot.team == Team.BLUE else Team.BLUE]

        # If team is falling behind, increase aggression
        if team_score < enemy_score - 20:
            # Increase exploration rate for learning
            self.exploration_rate = min(0.5, self.exploration_rate + 0.05)
            # Make AI more aggressive
            if robot.robot_type == RobotType.ASSAULT or robot.robot_type == RobotType.SCOUT:
                robot.speed *= 1.1  # Speed boost
                if robot.weapon:
                    robot.weapon.damage *= 1.05  # Slight damage boost

        # If team is winning, make AI more strategic and defensive
        elif team_score > enemy_score + 20:
            self.exploration_rate = max(0.1, self.exploration_rate - 0.05)
            # Make AI conserve resources
            if robot.robot_type == RobotType.SUPPORT:
                robot.speed *= 0.9  # Slight speed reduction to encourage positioning
            if robot.weapon:
                robot.weapon.fire_rate *= 1.1  # Reduce fire rate to encourage precision

        # Balance based on number of robots
        if len(allies) < len(enemies):
            # Team is outnumbered, increase defensive behavior
            if robot.robot_type == RobotType.TANK:
                robot.armor += 0.1  # Temporary armor boost
            if robot.robot_type == RobotType.SUPPORT:
                robot.abilities.append(Ability("shield", 10, 5, "shield", 15))

        # If team has more robots, encourage coordinated attacks
        elif len(allies) > len(enemies) + 2:
            # Increase coordination behavior
            self.exploration_rate = 0.2  # Less random, more coordinated
            # Add team coordination behavior

    def _record_decision(self, robot: Robot, action: Dict[str, Any], current_time: float) -> None:
        """Record robot's decision for learning"""
        decision = {
            "time": current_time,
            "action": action["action"],
            "target": action.get("target"),
            "reason": action.get("reason"),
            "health": robot.health,
            "team": robot.team,
            "robot_type": robot.robot_type.value,
            "enemy_count": len([r for r in self.game_state.robots if r.team != robot.team and r.is_alive]),
            "objective_status": [obj.status for obj in self.game_state.objectives]
        }

        robot.strategy_memory.append(decision)

        # Keep only last 50 decisions to avoid memory bloat
        if len(robot.strategy_memory) > 50:
            robot.strategy_memory.pop(0)

    def analyze_learning(self) -> Dict[str, float]:
        """Analyze robot learning patterns"""
        success_rate = 0
        total_decisions = 0
        for robot in self.game_state.robots:
            for decision in robot.strategy_memory:
                total_decisions += 1
                if decision["reason"] == "capture_flag" and self.game_state.get_robot_by_id(robot.id):
                    # Simulated success
                    success_rate += 1

        if total_decisions == 0:
            return {"learning_rate": 0.0}

        return {
            "learning_rate": success_rate / total_decisions,
            "total_decisions": total_decisions
        }

