class AudioVisualSystem:
    """Handles visual and audio effects"""

    def __init__(self):
        self.particle_systems = []
        self.sounds = {
            "fire": "ranged_fire.wav",
            "melee": "melee_hit.wav",
            "explosion": "explosion.wav",
            "heal": "heal_sound.wav",
            "powerup": "powerup_get.wav",
            "capture": "flag_capture.wav",
            "death": "robot_death.wav",
            "team_score": "team_score.wav"
        }

        self.lighting_effects = []
        self.map_lighting = {"ambient": 0.5, "dynamic": []}

    def create_explosion_effect(self, position: Vector2D, team: Team) -> None:
        """Create visual explosion effect"""
        explosion = {
            "position": position,
            "radius": 5.0,
            "duration": 1.5,
            "color": "red" if team == Team.RED else "blue",
            "start_time": time.time()
        }
        self.particle_systems.append(explosion)

        # Play explosion sound
        self._play_sound("explosion")

        # Create dynamic lighting
        self.map_lighting["dynamic"].append({
            "position": position,
            "intensity": 0.8,
            "radius": 15.0,
            "fade_time": 1.0,
            "start_time": time.time()
        })

    def create_heal_effect(self, position: Vector2D, team: Team) -> None:
        """Create visual heal effect"""
        heal = {
            "position": position,
            "radius": 3.0,
            "duration": 1.0,
            "color": "green",
            "start_time": time.time()
        }
        self.particle_systems.append(heal)
        self._play_sound("heal")

    def create_powerup_effect(self, powerup: PowerUp) -> None:
        """Create visual effect when power-up spawns"""
        effect = {
            "position": powerup.position,
            "radius": 2.0,
