            "type": powerup.type.value
        }
        self.particle_systems.append(effect)
        self._play_sound("powerup")

    def create_capture_effect(self, team: Team, objective: Objective) -> None:
        """Create visual effect when objective captured"""
        effect = {
            "position": objective.position,
            "radius": 8.0,
            "duration": 2.5,
            "color": "red" if team == Team.RED else "blue",
            "start_time": time.time(),
            "text": f"{team.value} Captured!"
        }
        self.particle_systems.append(effect)
        self._play_sound("capture")

    def create_death_effect(self, position: Vector2D, team: Team) -> None:
        """Create visual effect when robot dies"""
        effect = {
            "position": position,
            "radius": 4.0,
            "duration": 2.0,
            "color": "gray",
            "start_time": time.time(),
            "type": "death"
        }
        self.particle_systems.append(effect)
        self._play_sound("death")

    def create_smoke_effect(self, position: Vector2D, radius: float) -> None:
        """Create smoke effect for hazards"""
        effect = {
            "position": position,
            "radius": radius,
            "duration": 3.0,
            "color": "gray",
            "start_time": time.time(),
            "type": "smoke"
        }
        self.particle_systems.append(effect)

    def _play_sound(self, sound_name: str) -> None:
        """Simulate sound playing"""
        if sound_name in self.sounds:
            logger.info(f"PLAYING SOUND: {self.sounds[sound_name]}")

    def update_effects(self) -> None:
        """Update and remove expired effects"""
        current_time = time.time()
        self.particle_systems = [
            effect for effect in self.particle_systems 
            if current_time - effect["start_time"] < effect["duration"]
        ]

        # Update dynamic lighting
        self.map_lighting["dynamic"] = [
            light for light in self.map_lighting["dynamic"]
            if current_time - light["start_time"] < light["fade_time"]
        ]

        # Adjust ambient lighting based on active dynamic lights
        active_dynamic = len([light for light in self.map_lighting["dynamic"] 
                             if current_time - light["start_time"] < light["fade_time"]])
        self.map_lighting["ambient"] = 0.5 + min(active_dynamic * 0.1, 0.3)

