class CyberArena:
    """Main multi-agent battle arena system"""

    def __init__(self, width: float = 100.0, height: float = 100.0, num_robots: int = 8):
        self.width = width
        self.height = height
        self.state = GameState.PREPARING
        self.arena_size = Vector2D(width, height)

        # Game elements
        self.robots: List[Robot] = []
        self.objectives: List[Objective] = []
        self.power_ups: List[PowerUp] = []
        self.hazards: List[Hazard] = []

        # Game state tracking
        self.match_stats = MatchStatistics()
        self.time_elapsed = 0.0
        self.last_update_time = time.time()

        # AI learning parameters
        self.adaptive_difficulty = 1.0  # 0.5 to 2.0 scale
        self.learning_rate = 0.05
        self.strategy_improvement_threshold = 0.15
        self.total_battles = 0

        # Audio/visual effects (simulated)
        self.visual_effects = []
        self.audio_effects = []

        # Initialize game
        self.initialize_arena(num_robots)

    def initialize_arena(self, num_robots: int):
        """Initialize the arena with robots and objectives"""
        team_size = num_robots // 2
        remaining = num_robots % 2

        # Create robots for red team
        for i in range(team_size + remaining):
            role = random.choice(list(RobotRole))
            robot = Robot(
                id=f"Red{i}",
                team=Team.RED,
                role=role,
                position=Vector2D(
                    random.uniform(10, self.width/2 - 10),
                    random.uniform(10, self.height - 10)
                ),
                health=100.0
            )
            self.robots.append(robot)

        # Create robots for blue team
        for i in range(team_size):
            role = random.choice(list(RobotRole))
            robot = Robot(
                id=f"Blue{i}",
                team=Team.BLUE,
                role=role,
                position=Vector2D(
                    random.uniform(self.width/2 + 10, self.width - 10),
                    random.uniform(10, self.height - 10)
                ),
                health=100.0
            )
            self.robots.append(robot)

        # Create objectives
        self.objectives = [
            Objective(
                type=ObjectiveType.FLAG_CAPTURE,
                position=Vector2D(self.width * 0.25, self.height * 0.5),
                team_requirement=Team.NEUTRAL,
                capture_threshold=150.0,
                completion_reward=150
            ),
            Objective(
                type=ObjectiveType.FLAG_CAPTURE,
                position=Vector2D(self.width * 0.75, self.height * 0.5),
                team_requirement=Team.NEUTRAL,
                capture_threshold=150.0,
                completion_reward=150
            ),
            Objective(
                type=ObjectiveType.BASE_DEFENSE,
                position=Vector2D(self.width * 0.1, self.height * 0.2),
                team_requirement=Team.RED,
                capture_threshold=200.0,
                completion_reward=200
            ),
            Objective(
                type=ObjectiveType.BASE_DEFENSE,
                position=Vector2D(self.width * 0.9, self.height * 0.8),
                team_requirement=Team.BLUE,
                capture_threshold=200.0,
                completion_reward=200
            ),
            Objective(
                type=ObjectiveType.ESCORTE_PAYLOAD,
                position=Vector2D(self.width * 0.5, self.height * 0.1),
                team_requirement=Team.RED,
                capture_threshold=80.0,
                completion_reward=80
            )
        ]

        # Create power-ups
        power_up_types = list(PowerUpType)
        for _ in range(5):
            power_up = PowerUp(
                type=random.choice(power_up_types),
                position=Vector2D(
                    random.uniform(10, self.width - 10),
