@dataclass
class Vector2D:
    """2D position and velocity vector"""
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        return Vector2D(self.x / scalar, self.y / scalar)

    def magnitude(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        mag = self.magnitude()
        if mag == 0:
            return Vector2D(0, 0)
        return self / mag

    def distance_to(self, other):
        return (self - other).magnitude()

    def dot(self, other):
        return self.x * other.x + self.y * other.y

    def rotate(self, angle_rad):
        cos_a = math.cos(angle_rad)
        sin_a = math.sin(angle_rad)
        return Vector2D(
            self.x * cos_a - self.y * sin_a,
            self.x * sin_a + self.y * cos_a
        )

@dataclass
class Weapon:
    """Represents a weapon with properties"""
    name: str
    type: WeaponType
    damage: float
    range: float
    fire_rate: float  # seconds between shots
    ammo: int = -1  # -1 means infinite
    max_ammo: int = -1
    reload_time: float = 0.0
    splash_radius: float = 0.0
    cooldown: float = 0.0  # current cooldown timer

    def can_fire(self) -> bool:
        return self.cooldown <= 0 and (self.ammo > 0 or self.ammo == -1)

    def fire(self) -> Dict[str, Any]:
        """Fire the weapon and return firing details"""
        if not self.can_fire():
            return {"success": False}

        self.cooldown = self.fire_rate
        if self.ammo > 0:
            self.ammo -= 1

        return {
            "success": True,
            "damage": self.damage,
            "range": self.range,
            "splash_radius": self.splash_radius,
            "weapon_type": self.type
        }

    def update(self, delta_time: float):
        """Update cooldown timer"""
        if self.cooldown > 0:
            self.cooldown -= delta_time
            if self.cooldown < 0:
                self.cooldown = 0

