    armor: float = 0.0  # damage reduction
    weapons: List[Weapon] = field(default_factory=list)
    active_weapon_index: int = 0
    vision_range: float = 20.0
    is_alive: bool = True
    last_action_time: float = 0.0
    objectives: List[ObjectiveType] = field(default_factory=list)
    strategy_memory: Dict[str, float] = field(default_factory=dict)  # For learning
    power_ups: Dict[PowerUpType, float] = field(default_factory=dict)  # power_up_type -> duration
    last_seen_enemies: List[Dict] = field(default_factory=list)  # [{"id": str, "position": Vector2D, "time": float}]

    def __post_init__(self):
        if not self.weapons:
            # Default weapons for each role
            if self.role == RobotRole.ATTACKER:
                self.weapons = [
                    Weapon("Plasma Rifle", WeaponType.RANGED, 25, 30, 0.5, 30, 30, 1.5),
                    Weapon("Plasma Blade", WeaponType.MELEE, 40, 5, 2.0)
                ]
            elif self.role == RobotRole.DEFENDER:
                self.weapons = [
                    Weapon("Heavy Cannon", WeaponType.RANGED, 35, 25, 1.0, 20, 20, 2.5),
                    Weapon("Shield Generator", WeaponType.SPECIAL, 0, 10, 5.0, 1, 1, 10.0)
                ]
            elif self.role == RobotRole.SUPPORT:
                self.weapons = [
                    Weapon("Medi-Pulse", WeaponType.SPECIAL, 15, 20, 0.8, -1, -1, 0.5),
                    Weapon("Repair Drone", WeaponType.SPECIAL, 0, 15, 3.0, 1, 1, 8.0)
                ]
            elif self.role == RobotRole.SCOUT:
                self.weapons = [
                    Weapon("Sniper Rifle", WeaponType.RANGED, 50, 60, 1.5, 15, 15, 3.0),
                    Weapon("Cloaking Device", WeaponType.SPECIAL, 0, 10, 6.0, 1, 1, 12.0)
                ]
            elif self.role == RobotRole.CONTROLLER:
                self.weapons = [
                    Weapon("EMP Pulse", WeaponType.SPECIAL, 0, 25, 4.0, 5, 5, 10.0),
                    Weapon("Hacking Device", WeaponType.SPECIAL, 0, 18, 5.0, 1, 1, 15.0)
                ]
            self.active_weapon_index = 0

    def get_active_weapon(self) -> Weapon:
        """Return currently active weapon"""
        if 0 <= self.active_weapon_index < len(self.weapons):
            return self.weapons[self.active_weapon_index]
        return Weapon("No Weapon", WeaponType.RANGED, 0, 0, 1.0)

    def switch_weapon(self, direction: int = 1):
        """Switch to next weapon (direction: 1 for next, -1 for previous)"""
        if len(self.weapons) > 1:
            self.active_weapon_index = (self.active_weapon_index + direction) % len(self.weapons)

    def take_damage(self, amount: float, source: str = "unknown") -> float:
        """Apply damage with armor reduction"""
        if not self.is_alive:
            return 0.0

        reduction = self.armor * 0.1  # 10% reduction per armor point
        actual_damage = max(1.0, amount * (1 - reduction))
        self.health -= actual_damage

        if self.health <= 0:
            self.is_alive = False
            self.health = 0

        return actual_damage

    def heal(self, amount: float):
        """Heal the robot"""
        if not self.is_alive:
            return
        self.health = min(self.max_health, self.health + amount)

    def apply_power_up(self, power_type: PowerUpType, duration: float):
        """Apply a power-up effect"""
        self.power_ups[power_type] = duration
        # Apply immediate effects
        if power_type == PowerUpType.SPEED_BOOST:
            self.speed *= 1.5
        elif power_type == PowerUpType.DAMAGE_BOOST:
            for weapon in self.weapons:
                weapon.damage *= 1.3
        elif power_type == PowerUpType.SHIELD:
            self.armor += 20  # Temporary armor bonus

    def update_power_ups(self, delta_time: float):
        """Update active power-ups and remove expired ones"""
        expired = []
        for power_type, duration in self.power_ups.items():
            self.power_ups[power_type] = max(0, duration - delta_time)
            if self.power_ups[power_type] <= 0:
                expired.append(power_type)

        # Remove expired power-ups and restore base stats
        for power_type in expired:
            if power_type == PowerUpType.SPEED_BOOST:
                self.speed /= 1.5
            elif power_type == PowerUpType.DAMAGE_BOOST:
                for weapon in self.weapons:
                    weapon.damage /= 1.3
            elif power_type == PowerUpType.SHIELD:
                self.armor -= 20
            del self.power_ups[power_type]

    def update(self, delta_time: float):
        """Update robot state"""
        # Update weapon cooldowns
        for weapon in self.weapons:
            weapon.update(delta_time)

        # Update power-up durations
        self.update_power_ups(delta_time)

        # Update position based on velocity
        self.position += self.velocity * delta_time

        # Apply friction
        self.velocity *= 0.95 ** delta_time

        # Update strategy memory (decay over time)
        for key in list(self.strategy_memory.keys()):
            self.strategy_memory[key] *= 0.99  # Memory decay

        # Update last seen enemies
        self.last_seen_enemies = [
            enemy for enemy in self.last_seen_enemies 
            if time.time() - enemy["time"] < 5.0
        ]

    def get_perceived_enemies(self, arena: 'CyberArena') -> List['Robot']:
        """Get list of enemies within vision range"""
        enemies = []
        for robot in arena.robots:
            if robot.team != self.team and robot.is_alive:
                distance = self.position.distance_to(robot.position)
                if distance <= self.vision_range:
                    enemies.append(robot)
                    # Update last seen enemies
                    self.last_seen_enemies.append({
                        "id": robot.id,
                        "position": robot.position,
                        "time": time.time()
                    })
        return enemies

    def get_nearest_objective(self, arena: 'CyberArena') -> Optional[Dict]:
        """Find the nearest objective based on role"""
        if not self.objectives:
            return None

        best_objective = None
        min_distance = float('inf')

        for obj_type in self.objectives:
            for objective in arena.objectives:
                if objective.type == obj_type:
                    distance = self.position.distance_to(objective.position)
                    if distance < min_distance:
                        min_distance = distance
                        best_objective = objective

        return best_objective

    def get_action_recommendation(self, arena: 'CyberArena') -> str:
        """Use AI logic to determine best action based on role and situation"""
        enemies = self.get_perceived_enemies(arena)
        nearest_obj = self.get_nearest_objective(arena)
        active_weapon = self.get_active_weapon()

        # Check if we're under attack
        if enemies:
            closest_enemy = min(enemies, key=lambda e: self.position.distance_to(e.position))
            enemy_distance = self.position.distance_to(closest_enemy.position)

            # Use weapon range to determine engagement type
            if active_weapon.type == WeaponType.MELEE and enemy_distance <= active_weapon.range:
                return "MELEE_ATTACK"
            elif active_weapon.type == WeaponType.RANGED and enemy_distance <= active_weapon.range * 0.8:
                return "RANGED_ATTACK"
            elif active_weapon.type == WeaponType.RANGED and enemy_distance > active_weapon.range:
                return "MOVE_TOWARD_ENEMY"
            elif active_weapon.type == WeaponType.SPECIAL and enemy_distance <= 20:
                return "USE_SPECIAL"
            else:
                # Retreat if too close for ranged weapons or if low health
                if enemy_distance < 8 and active_weapon.type == WeaponType.RANGED:
                    return "RETREAT"
                elif self.health < self.max_health * 0.3:
                    return "RETREAT"
                else:
                    return "MOVE_TOWARD_ENEMY"

        # If no enemies and have objectives
        if nearest_obj:
            obj_distance = self.position.distance_to(nearest_obj.position)
            if obj_distance <= 5:  # Close enough to complete objective
                return "COMPLETE_OBJECTIVE"
            else:
                return "MOVE_TOWARD_OBJECTIVE"

        # Patrol or search behavior
        return "PATROL"

    def execute_action(self, action: str, arena: 'CyberArena') -> bool:
        """Execute the recommended action"""
        if not self.is_alive:
            return False

        enemies = self.get_perceived_enemies(arena)
        nearest_obj = self.get_nearest_objective(arena)
        active_weapon = self.get_active_weapon()

        if action == "MELEE_ATTACK":
            if enemies:
                closest_enemy = min(enemies, key=lambda e: self.position.distance_to(e.position))
                # Move toward enemy
                direction = (closest_enemy.position - self.position).normalize()
                self.velocity = direction * self.speed * 1.2
                # Attempt melee attack
                if self.position.distance_to(closest_enemy.position) <= active_weapon.range:
                    weapon_result = active_weapon.fire()
                    if weapon_result["success"]:
                        damage = weapon_result["damage"]
                        closest_enemy.take_damage(damage, self.id)
                        logger.info(f"{self.id} dealt {damage:.1f} damage to {closest_enemy.id} with melee")
                        return True

        elif action == "RANGED_ATTACK":
            if enemies:
                closest_enemy = min(enemies, key=lambda e: self.position.distance_to(e.position))
                # Move slightly toward enemy for better aim
                direction = (closest_enemy.position - self.position).normalize()
                self.velocity = direction * self.speed * 0.8

                # Fire if in range
                if self.position.distance_to(closest_enemy.position) <= active_weapon.range:
                    weapon_result = active_weapon.fire()
                    if weapon_result["success"]:
                        damage = weapon_result["damage"]
                        splash_radius = weapon_result["splash_radius"]
                        closest_enemy.take_damage(damage, self.id)
                        logger.info(f"{self.id} dealt {damage:.1f} damage to {closest_enemy.id} with ranged")

                        # Apply splash damage if applicable
                        if splash_radius > 0:
                            for enemy in enemies:
                                if enemy != closest_enemy and self.position.distance_to(enemy.position) <= splash_radius:
                                    enemy.take_damage(damage * 0.3, self.id)
                        return True

        elif action == "USE_SPECIAL":
            if active_weapon.type == WeaponType.SPECIAL:
                weapon_result = active_weapon.fire()
                if weapon_result["success"]:
                    if active_weapon.name == "Medi-Pulse":
                        # Heal allies in range
                        for robot in arena.robots:
                            if robot.team == self.team and robot.is_alive and self.position.distance_to(robot.position) <= active_weapon.range:
                                robot.heal(active_weapon.damage)
                    elif active_weapon.name == "Shield Generator":
                        # Apply shield to self
                        self.armor += 15
                    elif active_weapon.name == "EMP Pulse":
                        # Disable weapons of enemies in range
                        for enemy in enemies:
                            if self.position.distance_to(enemy.position) <= active_weapon.range:
                                for weapon in enemy.weapons:
                                    weapon.cooldown = weapon.fire_rate * 2
                    elif active_weapon.name == "Cloaking Device":
                        # Become invisible for a period
                        self.vision_range = 5.0
                        # This would be handled by a timer in a full implementation
                    elif active_weapon.name == "Hacking Device":
                        # Take control of an enemy robot temporarily
                        if enemies:
                            target = min(enemies, key=lambda e: self.position.distance_to(e.position))
                            # In a full implementation, this would temporarily switch team control
                            logger.info(f"{self.id} hacked {target.id}!")
                    logger.info(f"{self.id} used special weapon: {active_weapon.name}")
                    return True

        elif action == "MOVE_TOWARD_ENEMY":
            if enemies:
                closest_enemy = min(enemies, key=lambda e: self.position.distance_to(e.position))
                direction = (closest_enemy.position - self.position).normalize()
                self.velocity = direction * self.speed
                return True

        elif action == "MOVE_TOWARD_OBJECTIVE":
            if nearest_obj:
                direction = (nearest_obj.position - self.position).normalize()
                self.velocity = direction * self.speed
                return True

        elif action == "COMPLETE_OBJECTIVE":
            if nearest_obj:
                # Complete the objective
                nearest_obj.complete(self.team)
                logger.info(f"{self.id} completed objective: {nearest_obj.type.value}")
                return True

        elif action == "RETREAT":
            # Move away from nearest enemy
            if enemies:
                closest_enemy = min(enemies, key=lambda e: self.position.distance_to(e.position))
                direction = (self.position - closest_enemy.position).normalize()
                self.velocity = direction * self.speed * 0.7
                return True

        elif action == "PATROL":
            # Simple patrol behavior - move in a random direction
            if random.random() < 0.3:  # 30% chance to change direction
                angle = random.uniform(0, math.pi * 2)
                direction = Vector2D(math.cos(angle), math.sin(angle))
                self.velocity = direction * self.speed * 0.5
            return True

        return False

@dataclass
class Objective:
    """Represents a game objective that robots must complete"""
    type: ObjectiveType
    position: Vector2D
    captured_by: Optional[Team] = None
    capture_progress: float = 0.0
    capture_threshold: float = 100.0
    team_requirement: Team = Team.NEUTRAL
    is_active: bool = True
    completion_reward: float = 100.0  # Points awarded for completion

    def complete(self, team: Team) -> bool:
        """Complete the objective for the given team"""
        if self.is_active and (self.team_requirement == Team.NEUTRAL or self.team_requirement == team):
            self.captured_by = team
            self.is_active = False
            logger.info(f"Objective {self.type.value} captured by {team.value}")
            return True
        return False

    def update(self, robots: List[Robot], delta_time: float):
        """Update objective capture progress based on nearby robots"""
        if not self.is_active:
            return

        # Count robots from each team near objective
        team_counts = {Team.RED: 0, Team.BLUE: 0}
        for robot in robots:
            if robot.is_alive and robot.position.distance_to(self.position) <= 8.0:
                team_counts[robot.team] += 1

        # Calculate progress based on team presence
        if team_counts[Team.RED] > team_counts[Team.BLUE]:
            self.capture_progress = min(self.capture_threshold, self.capture_progress + team_counts[Team.RED] * 3 * delta_time)
            self.captured_by = Team.RED
        elif team_counts[Team.BLUE] > team_counts[Team.RED]:
            self.capture_progress = min(self.capture_threshold, self.capture_progress + team_counts[Team.BLUE] * 3 * delta_time)
            self.captured_by = Team.BLUE
        else:
            # Equal presence - slow progress toward neutral
            self.capture_progress = max(0, self.capture_progress - 1 * delta_time)
            self.captured_by = None

@dataclass
class PowerUp:
    """Represents a power-up item in the arena"""
    type: PowerUpType
    position: Vector2D
    duration: float = 10.0  # seconds
    active: bool = True
    spawn_time: float = field(default_factory=lambda: time.time())
    respawn_time: float = 30.0  # seconds until respawn

    def get_effect(self) -> Dict[str, Any]:
        """Return effect of this power-up"""
        return {
            "type": self.type,
            "duration": self.duration,
            "position": self.position
        }

    def update(self, delta_time: float):
        """Update power-up state"""
        if not self.active and time.time() - self.spawn_time > self.respawn_time:
            self.active = True
            self.spawn_time = time.time()

@dataclass
class Hazard:
    """Represents a hazardous environmental effect"""
    type: HazardType
    position: Vector2D
    radius: float = 5.0
    damage_per_second: float = 5.0
    active: bool = True
    spawn_time: float = field(default_factory=lambda: time.time())
    duration: float = 60.0  # seconds

    def apply_damage(self, robot: Robot, delta_time: float) -> float:
        """Apply damage to robot if within range"""
        if not self.active:
            return 0.0

        distance = robot.position.distance_to(self.position)
        if distance <= self.radius:
            damage = self.damage_per_second * delta_time
            return robot.take_damage(damage, f"{self.type.value}")
        return 0.0

@dataclass
class MatchStatistics:
    """Track match statistics for adaptive difficulty"""
    team_stats: Dict[Team, Dict[str, Any]] = field(default_factory=lambda: {
        Team.RED: {"kills": 0, "deaths": 0, "objectives_completed": 0, "assists": 0, "time_alive": 0},
        Team.BLUE: {"kills": 0, "deaths": 0, "objectives_completed": 0, "assists": 0, "time_alive": 0}
    })
    match_start_time: float = field(default_factory=time.time)
    rounds_completed: int = 0

    def update(self, team: Team, stat_type: str, value: float = 1.0):
        """Update a specific statistic"""
        self.team_stats[team][stat_type] += value

    def get_team_performance(self, team: Team) -> float:
        """Calculate team performance score (0-1)"""
        stats = self.team_stats[team]
        kills = stats["kills"]
        deaths = stats["deaths"]
        objectives = stats["objectives_completed"]
        assists = stats["assists"]

        # Calculate performance score (heavily weighted on objectives and kills)
        if deaths == 0:
            kd_ratio = kills
        else:
            kd_ratio = kills / deaths

        # Normalize to 0-1 range
        score = min(1.0, (kills * 0.4 + objectives * 0.3 + assists * 0.2 + kd_ratio * 0.1) / 10)
        return score

    def get_average_performance(self) -> float:
        """Get average performance across teams"""
        return (self.get_team_performance(Team.RED) + self.get_team_performance(Team.BLUE)) / 2

