class CyberArena:
    """Main multi-agent battle arena system"""

    def __init__(self, width: float = 100.0, height: float = 100.0, num_robots: int = 8):
        self.width = width
        self.height = height
        self.state = GameState.PREPARING
        self.arena_size = Vector2D(width, height)

        # Game elements
        self.robots: List[Robot] = []
        self.objectives: List[Objective] = []
        self.power_ups: List[PowerUp] = []
        self.hazards: List[Hazard] = []

        # Game state tracking
        self.match_stats = MatchStatistics()
        self.time_elapsed = 0.0
        self.last_update_time = time.time()

        # AI learning parameters
        self.adaptive_difficulty = 1.0  # 0.5 to 2.0 scale
        self.learning_rate = 0.05
        self.strategy_improvement_threshold = 0.15
        self.total_battles = 0

        # Audio/visual effects (simulated)
        self.visual_effects = []
        self.audio_effects = []

        # Initialize game
        self.initialize_arena(num_robots)

    def initialize_arena(self, num_robots: int):
        """Initialize the arena with robots and objectives"""
        team_size = num_robots // 2
        remaining = num_robots % 2

        # Create robots for red team
        for i in range(team_size + remaining):
            role = random.choice(list(RobotRole))
            robot = Robot(
                id=f"Red{i}",
                team=Team.RED,
                role=role,
                position=Vector2D(
                    random.uniform(10, self.width/2 - 10),
                    random.uniform(10, self.height - 10)
                ),
                health=100.0
            )
            self.robots.append(robot)

        # Create robots for blue team
        for i in range(team_size):
            role = random.choice(list(RobotRole))
            robot = Robot(
                id=f"Blue{i}",
                team=Team.BLUE,
                role=role,
                position=Vector2D(
                    random.uniform(self.width/2 + 10, self.width - 10),
                    random.uniform(10, self.height - 10)
                ),
                health=100.0
            )
            self.robots.append(robot)

        # Create objectives
        self.objectives = [
            Objective(
                type=ObjectiveType.FLAG_CAPTURE,
                position=Vector2D(self.width * 0.25, self.height * 0.5),
                team_requirement=Team.NEUTRAL,
                capture_threshold=150.0,
                completion_reward=150
            ),
            Objective(
                type=ObjectiveType.FLAG_CAPTURE,
                position=Vector2D(self.width * 0.75, self.height * 0.5),
                team_requirement=Team.NEUTRAL,
                capture_threshold=150.0,
                completion_reward=150
            ),
            Objective(
                type=ObjectiveType.BASE_DEFENSE,
                position=Vector2D(self.width * 0.1, self.height * 0.2),
                team_requirement=Team.RED,
                capture_threshold=200.0,
                completion_reward=200
            ),
            Objective(
                type=ObjectiveType.BASE_DEFENSE,
                position=Vector2D(self.width * 0.9, self.height * 0.8),
                team_requirement=Team.BLUE,
                capture_threshold=200.0,
                completion_reward=200
            ),
            Objective(
                type=ObjectiveType.ESCORTE_PAYLOAD,
                position=Vector2D(self.width * 0.5, self.height * 0.1),
                team_requirement=Team.RED,
                capture_threshold=80.0,
                completion_reward=80
            )
        ]

        # Create power-ups
        power_up_types = list(PowerUpType)
        for _ in range(5):
            power_up = PowerUp(
                type=random.choice(power_up_types),
                position=Vector2D(
                    random.uniform(10, self.width - 10),
                    random.uniform(10, self.height - 10)
                )
            )
            self.power_ups.append(power_up)

        # Create hazards
        hazard_types = list(HazardType)
        for _ in range(3):
            hazard = Hazard(
                type=random.choice(hazard_types),
                position=Vector2D(
                    random.uniform(10, self.width - 10),
                    random.uniform(10, self.height - 10)
                ),
                damage_per_second=random.uniform(4, 8),
                radius=random.uniform(6, 10)
            )
            self.hazards.append(hazard)

        self.state = GameState.ACTIVE

    def update(self, delta_time: float):
        """Update the entire arena state"""
        if self.state != GameState.ACTIVE:
            return

        self.time_elapsed += delta_time
        current_time = time.time()

        # Update robots
        for robot in self.robots:
            if robot.is_alive:
                # Calculate action recommendation based on current state
                action = robot.get_action_recommendation(self)
                robot.execute_action(action, self)

                # Update robot state
                robot.update(delta_time)

                # Update team statistics
                self.match_stats.update(robot.team, "time_alive", delta_time)

                # Check for power-up collection
                for power_up in self.power_ups:
                    if power_up.active and robot.position.distance_to(power_up.position) < 3.0:
                        effect = power_up.get_effect()
                        robot.apply_power_up(effect["type"], effect["duration"])
                        power_up.active = False
                        # Create visual effect
                        self.visual_effects.append({
                            "type": "power_up_collect",
                            "position": robot.position,
                            "time": current_time
                        })
                        logger.info(f"{robot.id} collected {effect['type'].value} power-up")

        # Update objectives
        for objective in self.objectives:
            objective.update(self.robots, delta_time)
            if objective.captured_by and not objective.is_active:
                # Award points when objective is completed
                self.match_stats.update(objective.captured_by, "objectives_completed")
                # Add visual effect
                self.visual_effects.append({
                    "type": "objective_completed",
                    "position": objective.position,
                    "team": objective.captured_by,
                    "time": current_time
                })

        # Update power-ups
        for power_up in self.power_ups:
            power_up.update(delta_time)

        # Update hazards
        for hazard in self.hazards:
            # Apply damage to robots
            for robot in self.robots:
                if robot.is_alive:
                    damage = hazard.apply_damage(robot, delta_time)
                    if damage > 0:
                        # Create visual effect
                        self.visual_effects.append({
                            "type": "hazard_damage",
                            "position": robot.position,
                            "time": current_time
                        })
                        logger.info(f"{robot.id} took {damage:.1f} damage from {hazard.type.value}")

            # Hazard expiration
            if hazard.active and time.time() - hazard.spawn_time > hazard.duration:
                hazard.active = False

        # Update visual effects
        self.visual_effects = [
            effect for effect in self.visual_effects 
            if current_time - effect["time"] < 5.0
        ]

        # Adaptive difficulty adjustment
        self.adjust_difficulty()

        # Check for match end conditions
        self.check_match_end()

    def adjust_difficulty(self):
        """Adjust AI difficulty based on team performance"""
        avg_performance = self.match_stats.get_average_performance()

        # Adjust difficulty based on average performance
        # If teams are too dominant, increase difficulty to balance
        if avg_performance > 0.7:
            self.adaptive_difficulty = min(2.0, self.adaptive_difficulty * 1.05)
