    TRANSFORMATION = "transformation"
    EXPORT = "export"

class DataFormat(Enum):
    CSV = "csv"
    EXCEL = "excel"
    DATABASE = "database"

class ValidationResult:
    def __init__(self, is_valid: bool, errors: List[str], warnings: List[str]):
        self.is_valid = is_valid
        self.errors = errors
        self.warnings = warnings

    def __str__(self):
        if self.is_valid:
            return "Validation passed."
        else:
            return f"Validation failed with {len(self.errors)} errors: {self.errors}"

@dataclass
class DataFlowState:
    data: Optional[pd.DataFrame] = None
    stage: Optional[DataStage] = None
    metadata: Dict[str, Any] = None

    def __post_init__(self):
        if self.metadata is None:
            self.metadata = {}

class DataIngestionModule:
    def __init__(self):
        self.state = DataFlowState()

    def ingest(self, source: str, format_type: DataFormat, **kwargs) -> DataFlowState:
        """Ingest data from CSV, Excel, or database."""
        try:
            if format_type == DataFormat.CSV:
                self.state.data = pd.read_csv(source, **kwargs)
            elif format_type == DataFormat.EXCEL:
                self.state.data = pd.read_excel(source, **kwargs)
            elif format_type == DataFormat.DATABASE:
                connection_str = kwargs.get("connection_string")
                query = kwargs.get("query")
                if not connection_str or not query:
                    raise ValueError("For database ingestion, 'connection_string' and 'query' must be provided.")
                conn = sqlite3.connect(connection_str)  # Simplified for SQLite; extendable
                self.state.data = pd.read_sql_query(query, conn)
                conn.close()
            else:
                raise ValueError(f"Unsupported format: {format_type}")

            # Validate basic structure
            if self.state.data is None or len(self.state.data) == 0:
                raise ValueError("Ingested data is empty.")

            self.state.stage = DataStage.INGESTION
            self.state.metadata["source"] = source
            self.state.metadata["format"] = format_type.value
            self.state.metadata["rows"] = len(self.state.data)
            self.state.metadata["columns"] = list(self.state.data.columns)
            return self.state

        except Exception as e:
            raise RuntimeError(f"Data ingestion failed: {str(e)}")

class DataValidationModule:
    def __init__(self):
        self.state = DataFlowState()

    def validate(self, input_state: DataFlowState) -> ValidationResult:
        """Perform comprehensive data validation."""
        if input_state.stage != DataStage.INGESTION:
            raise RuntimeError("Validation must follow ingestion.")

        errors = []
        warnings = []
        data = input_state.data

        # Check for nulls in required columns (assumed non-nullable unless specified)
        for col in data.columns:
            null_count = data[col].isnull().sum()
            if null_count > 0:
                if null_count == len(data):
                    errors.append(f"Column '{col}' is entirely null.")
                else:
                    warnings.append(f"Column '{col}' has {null_count} null values.")

        # Check data types (basic)
        # Assume all columns should be of consistent type
        for col in data.columns:
            if data[col].dtype == 'object':
                # Check if object column contains mixed types
                types = data[col].apply(type).unique()
                if len(types) > 1:
                    warnings.append(f"Column '{col}' contains mixed data types: {types}")

        # Check for duplicate rows
        duplicate_count = data.duplicated().sum()
        if duplicate_count > 0:
            warnings.append(f"Found {duplicate_count} duplicate rows.")

        # Check for empty columns
        empty_cols = data.columns[data.isnull().all()].tolist()
        if empty_cols:
            errors.append(f"Empty columns detected: {empty_cols}")

        is_valid = len(errors) == 0
        return ValidationResult(is_valid=is_valid, errors=errors, warnings=warnings)

    def execute(self, input_state: DataFlowState) -> DataFlowState:
        """Execute validation and update state."""
        validation_result = self.validate(input_state)
        if not validation_result.is_valid:
            raise ValueError(f"Data validation failed: {validation_result.errors}")

        self.state = input_state  # Pass-through validated data
        self.state.stage = DataStage.VALIDATION
        self.state.metadata["validation_result"] = validation_result
        return self.state

class DataTransformationModule:
    def __init__(self):
        self.state = DataFlowState()

    def transform(self, input_state: DataFlowState, transformations: List[Callable]) -> DataFlowState:
        """Apply a list of transformation functions to data."""
        if input_state.stage != DataStage.VALIDATION:
            raise RuntimeError("Transformation must follow validation.")

        data = input_state.data.copy()
        for transform_func in transformations:
            try:
                data = transform_func(data)
            except Exception as e:
                raise RuntimeError(f"Transformation failed: {str(e)}")

        self.state.data = data
        self.state.stage = DataStage.TRANSFORMATION
        self.state.metadata.update(input_state.metadata)
        self.state.metadata["transformations_applied"] = len(transformations)
        return self.state

